كر‬   ‫‪45‬‬\n           ‫ولقيادة األول السيارة حتت تأثير املسكر‬\n                 ‫واالعتداء على مركبة رسمية‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪271‬‬     ‫عليه و بتعزيره لسرقته سيارة وتشديد العقوبة‬     ‫شرب مسكر‬   ‫‪46‬‬\n                       ‫عليه لسوابقه‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪277‬‬       ‫عليه و بتعزيره لقيادته للسيارة حتت تأثير‬     ‫شرب مسكر‬   ‫‪47‬‬\n                          ‫املسكر‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪283‬‬     ‫عليه و بتعزيره حليازته وتعاطيه للحشيش املخدر‬   ‫شرب مسكر‬   ‫‪48‬‬\n                      ‫ومنعه من السفر‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪290‬‬                                                    ‫شرب مسكر‬   ‫‪49‬‬\n          ‫عليهما وبتعزير اآلخِ ر حملاولته دهس األول‬\n\f‫الصفحة‬                     ‫املوضوع‬                        ‫التصنيف‬     ‫م‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪299‬‬        ‫عليه و بتعزيره إلحداثه الفوضى بإثارة‬         ‫شرب مسكر‬     ‫‪50‬‬\n                     ‫املشاكل مع أخيه‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهما ( رجل وامرأة‬\n ‫‪307‬‬     ‫تصنيع مسكر مقيمني ) بتصنيع وترويج اخلمور املصنعة محليا‬       ‫‪51‬‬\n                           ‫( العرق )‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهما لتصنيعهما‬\n          ‫(العرق ) املسكر وحيازتهما له بقصد الترويج‬\n ‫‪315‬‬                                                 ‫تصنيع مسكر‬       ‫‪52‬‬\n         ‫وإقامة حد املسكر على اآلخِ ر وتشديد العقوبة‬\n                        ‫عليه لسوابقه‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه ( أجنبي غير‬\n ‫‪326‬‬      ‫مسلم ) لتصنيعه قارورتني من اخلمر املسكر‬        ‫تصنيع مسكر‬   ‫‪53‬‬\n                ‫بقصد الشرب وشربه املسكر‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪332‬‬      ‫عليهما الثالث والرابع و بتعزير األول والثاني‬   ‫تصنيع مسكر‬   ‫‪54‬‬\n             ‫لتصنيعهما املسكر بقصد االستعمال‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته املسكر‬\n ‫‪341‬‬                                                     ‫حيازة مسكر‬   ‫‪55‬‬\n                   ‫يف السيارة التي يقودها‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لتستره وتعاونه‬\n ‫‪345‬‬     ‫مع مجهولي الهوية يف حيازة املسكرات بقصد‬         ‫حيازة مسكر‬   ‫‪56‬‬\n                             ‫بيعها‬\n\f‫الصفحة‬                    ‫املوضوع‬                       ‫التصنيف‬     ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته املسكر‬\n ‫‪355‬‬                                                   ‫حيازة مسكر‬   ‫‪57‬‬\n                        ‫بقصد الشرب‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليهما حليازتهما‬\n            ‫للعرق املسكر بقصد الترويج واالستعمال‬\n ‫‪360‬‬                                                   ‫حيازة مسكر‬   ‫‪58‬‬\n         ‫ومقاومة رجال هيئة األمر باملعروف وإلقامتهما‬\n                  ‫يف البالد بطريقة غير نظامية‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه األول حليازته‬\n ‫‪366‬‬     ‫املسكر بقصد الشرب وبتعزير املدعى عليهم‬        ‫حيازة مسكر‬   ‫‪59‬‬\n           ‫اآلخرين بالتستر على وجود املسكر معه‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪372‬‬                                                   ‫حيازة مسكر‬   ‫‪60‬‬\n          ‫عليه و بتعزيره حليازته مادة العرق املسكر‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n           ‫عليه وبتعزيره لتعاطيه احلبوب احملظورة‬\n ‫‪377‬‬                                                   ‫حيازة مسكر‬   ‫‪61‬‬\n         ‫والشتراكه ومرافقه يف حيازة قارورة مسكر‬\n                      ‫ومنعه من السفر‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n ‫‪384‬‬      ‫عليه وبتعزيره حليازته والهرب من رجال األمن‬   ‫حيازة مسكر‬   ‫‪62‬‬\n              ‫وقيادة السيارة حتت تأثير املسكر‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه اخلمور‬\n ‫‪393‬‬                                                   ‫ترويج مسكر‬   ‫‪63‬‬\n                   ‫وتستره على مصادر البيع‬\n\f‫الصفحة‬                    ‫املوضوع‬                        ‫التصنيف‬      ‫م‬\n\n\n         ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n           ‫عليه األول وبتعزير األول والثاني لترويج‬\n ‫‪398‬‬                                                    ‫ترويج مسكر‬    ‫‪64‬‬\n         ‫املسكر وحيازته وتعزير الثالث والرابع (غير‬\n               ‫مسلمني) على شربهما املسكر‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه الستنشاقه‬\n ‫‪411‬‬     ‫البنزين وحيازته لقارورة حتتوي على تلك املادة‬   ‫تشفيط بنزين‬   ‫‪68‬‬\n                       ‫بقصد االستنشاق‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":411,"source_page_end":427,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6aae8b6c5fa7dbb15beefa7fc5b73d32a6ad0141f2d40d8a4a6864c8635cdb47","normalized_text_hash":"c0b080bc7d8395465fae5aab94a3c96f50eb7687e655ce5e08da36939da7a524","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p411-34280904"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

