SELECT 'moj-all-verified-judgments-review-002-chunk-059' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"9fb8a426-51b1-52f5-ab9a-ddcb73aa17c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة املسكر -كبر حجم الكمية املضبوطة قرينة على االجتار والترويج -إقرار املدعى عليه -تشديد العقوبة لكونها يف بلد اهلل احلرام -حد املسكر -تعزير بالسجن واجللد.","document_number":"34176363","case_number":"34143444","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بدون الئحة اعتراضية وقنع به املدعى عليه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/28","year":"1434","subject":"مسكر -شرب املسكر -حيازة املسكر -كبر حجم الكمية املضبوطة قرينة على االجتار والترويج -إقرار املدعى عليه -تشديد العقوبة لكونها يف بلد اهلل احلرام -حد املسكر -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34176363:‬تاريخه ‪ 1434/03/28 :‬هـ‬\n                        ‫رقم الدعوى ‪34143444 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34206198:‬‬\n                           ‫تاريخه‪1434/05/05:‬ه‬\n\n\n         ‫مســكر‪ -‬شــرب املســكر ‪ -‬حيــازة املســكر ‪ -‬كبــر حجــم الكميــة املضبوطــة‬\n         ‫قرينــة علــى االجتــار والترويــج ‪ -‬إقــرار املدعــى عليــه ‪ -‬تشــديد العقوبــة‬\n              ‫لكونهــا يف بلــد اهلل احلــرام ‪ -‬حــد املســكر ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n         ‫‪ -‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                                           ‫حــرام )‪.‬‬\n         ‫‪ -‬إجمــاع العلمــاء علــى أن مــن شــرب املســكر حالــة كونــه طائعا مختارا‬\n                                                         ‫فيقــام عليــه حد املســكر‪.‬‬\n\n\n\n\n         ‫مت توجيــه االتهــام للمدعــى عليــه بتعاطــي وحيــازة العــرق املســكر يف‬\n         ‫املدينــة النبويــة‪ ،‬وذلــك بعــد ورود بــاغ للجهــات املختصــة يفيــد قيــام‬\n         ‫شــخص بوضــع أكيــاس داخــل ســيارة متعطلــة فتــم القبــض عليــه‪،‬‬\n         ‫ووجــد بحوزتــه ثالثــة قواريــر مســكر ‪ ،‬بالبحــث عــن ســوابقه لــم يعثــر‬\n         ‫لــه علــى ســوابق‪ ،‬بعــرض ذلــك علــى املدعــى عليــه صــادق علــى شــرب‬\n         ‫املســكر وحيازتــه لــه بقصــد الشــرب‪( ،‬طلــب املدعــي العــام احلكــم‬\n         ‫بحــد املســكر وبعقوبــة تعزيريــة لقــاء حيازتــه لــه) باالطــاع علــى‬\n         ‫التقريــر الفنــي املتضمــن إيجابيــة العينــة ملــادة الكحــول املســكرة ‪،‬‬\n\n                                                                                             ‫‪372‬‬\n\f      ‫وألن املدعــى عليــه أقــر بشــرب العــرق املســكر وحيازتــه ومبــا أن كميــة‬\n      ‫املســكر املضبوطــة بحــوزة املدعــى عليــه كثيــرة وهــذه قرينــة تقــوي‬\n      ‫الشــبهة بــأن الغــرض مــن احليــازة الترويــج ومبــا أن هــذه اجلنايــة وقعــت يف‬\n      ‫بلــد اهلل احلــرام الــذي رفــع اهلل مكانــه وتوعــد بالعقــاب علــى مــن انتهــك‬\n      ‫محارمــه ومبــا أن التعزيــر يجــب للشــبهة وهــو مشــروع يف كل معصيــة‬\n      ‫ال حــد فيهــا وال كفــارة وهــو يختلــف باختــاف األحــوال واألشــخاص‬\n      ‫والزمــان واملــكان وتقديــر ذلــك راجــع إلــى نظــر احلاكــم ومبــا يــراه‬\n      ‫محققــا للزجــر والــردع‪ ،‬جلميــع ذلــك كلــه مت احلكــم بجلــد املدعــى‬\n      ‫عليــه ثمانــن جلــدة حــد املســكر دفعــة واحــدة أمــام جمــع مــن النــاس‬\n      ‫وتعزيــره بجلــده مائتــي جلــدة علــى أربــع دفعــات متســاويات وســجنه‬\n      ‫خمســة أشــهر‪ ،‬بعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه‬\n      ‫قــرر املدعــي العــام عــدم قناعتــه باحلكــم وطلــب رفعــه إلــي محكمــة‬\n      ‫االســتئناف بــدون الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه‪ ،‬وبعــد رفــع‬\n                            ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34143444‬وتاريــخ‬\n      ‫‪ 1434/03/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34762502‬وتاريــخ‬\n      ‫‪ 1434/03/28‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/04/01‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 9 : 00‬وفيهــا حضــر املدعــي العــام بهيئــة التحقيــق‬\n      ‫واالدعــاء العــام باملدينــة املنــورة ‪.....‬وادعــى علــى احلاضــر معــه مبجلــس‬\n\n‫‪373‬‬\n\f‫احلكــم ‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائــا يف‬\n‫حتريــر دعــواه إنــه بتاريــخ ‪1434/2/6‬ه ـ انتقلــت الدوريــات األمنيــة‬\n‫بنــاء علــى البــاغ الــوارد مــن املبلغــة ‪.....‬حيــث أفــادت بوجــود شــخص‬\n‫يقــود ســيارة ‪ ....‬قــام بوضــع أكيــاس داخــل ســيارة ‪ ....‬متعطلــة أمــام‬\n‫منزلهــا وبالبحــث عــن قائــد الســيارة تبــن أنــه املدعــى عليــه وعنــد‬\n‫إســتيقافه وجــد بحوزتــه (‪ )3‬قواريــر ســعة لتــر كمــا وجــد بداخــل ‪....‬‬\n‫العائــد لــه (‪ )24‬قــارورة ســعة لتــر بهــا مــادة يشــتبه بــأن تكــون مــادة‬\n‫العــرق املســكر وباســتجوابه أنكــر حيازتــه للعــرق املســكر واعتــرف‬\n‫بتناولــه مــادة العــرق املســكر وتبــن مــن خــال التقريــر الفنــي رقــم ‪.....‬‬\n‫وتاريــخ ‪1434‬ه ـ املرفــق إيجابيــة عينــة املــادة املضبوطــة للكحــول بنســبة‬\n‫‪ %45‬وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بتعاطــي وحيــازة العــرق‬\n‫املســكر وذلــك لألدلــة والقرائــن التاليــة ‪ -1‬مــا جــاء مبحضــر القبــض‬\n‫املتضمــن القبــض عليــه وبحوزتــه (‪ )27‬قــارورة مــن العــرق املســكر لفــة‬\n‫(‪ -2 )2‬اعترافــه بتعاطــي املســكر املصــدق عليــه شــرعا ‪ -3‬اعترافــه‬\n‫لرجــال األمــن عنــد القبــض عليــه أن املضبوطــات عائــدة لــه ‪ -4‬مــا‬\n‫جــاء بالتقريــر الفنــي إيجابيــة العينــة للمــواد املســكرة ‪ -5‬مــا تضمنــه‬\n‫محضــر الدوريــات أن املبلغــة شــاهدت املذكــور يقــوم بوضــع أكيــاس‬\n‫داخــل ســيارتها املتعطلــة أمــام منزلهــا وبالبحــث عــن ســوابقه لــم يعثــر لــه‬\n‫علــى ســابقة وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب‬\n‫عليــه شــرعا أطلــب إثبــات مــا نســب إليــه واحلكــم عليــه بحــد املســكر‬\n‫و بعقوبــة تعزيريــة لقــاء حيــازة مــادة العــرق املســكر واملدعــى عليــه‬\n‫ســجني علــى ذمــة هــذه القضيــة منــذ تاريــخ ‪ 1434/2/6‬ه ـ هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعــي العــام أجــاب قائــا مــا‬\n\n\n                                                                                       ‫‪374‬‬\n\f      ‫ذكــره املدعــي العــام يف دعــواه صحيــح جملــة وتفصيــا ففــي التاريــخ‬\n      ‫املذكــور يف الدعــوى قبــض علــى رجــال األمــن بحــي ‪.....‬باملدينــة املنــورة‬\n      ‫وقــد ضبطــوا بحوزتــي ثــاث قواريــر مــن العــرق املســكر كمــا ضبطــوا‬\n      ‫أربعــة وعشــرين قــارورة داخــل الســيارة املذكــورة يف الدعــوى مملــوءة‬\n      ‫جميعهــا بالعــرق املســكر وهــي لــي شــخصيا لغــرض االســتعمال حيــث‬\n      ‫إنــي أســتعمل العــرق املســكر منــذ فتــرة و أنــا نــادم وتائــب هكــذا‬\n      ‫أجــاب عقــب ذلــك قــال املدعــي العــام إن الكميــة املضبوطــة مــع املدعــى‬\n      ‫عليــه كثيــرة و هــذه قرينــة قويــة تديــن املدعــى عليــه بــأن غرضــه مــن‬\n      ‫احليــازة للترويــج و ال بينــة لــي غيــر ذلــك وبعرضــه علــى املدعــى عليــه رد‬\n      ‫قائــا إن غرضــي مــن احليــازة هــو االســتعمال الشــخصي و أنــا أشــرب‬\n      ‫املســكر بكثــرة هــذا وبالرجــوع إلــي املعاملــة وجــد فيهــا التقريــر الفنــي‬\n      ‫رقــم‪ 1434.....‬ه ـ يف ‪ 1434/2/9‬ه ـ واملتضمــن الكشــف علــى العينــات‬\n      ‫املرســلة وهــي مجموعــة مــن القواريــر فيهــا ســائل شــفاف ثبــت إيجابيتهــا‬\n      ‫جميعــا ملــادة الكحــول املســكرة وقــد أتلفــت جميــع املضبوطــات فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى‬\n      ‫دعــوى املدعــي العــام فأقــر بشــرب العــرق املســكر وحيازتــه ومبــا أن‬\n      ‫العلمــاء قــد أجمعــوا علــى أن مــن شــرب املســكر حالــة كونــه طائعــا‬\n      ‫مختــارا فيقــام عليــه حــد املســكر لعمــوم قــول النبــي صلــي اهلل عليــه‬\n      ‫وســلم ( كل مســكر خمــر وكل خمــر حــرام ) ومبــا أن الكميــة‬\n      ‫املســكر املضبوطــة بحــوزة املدعــى عليــه كثيــرة وهــذه قرينــة تقــوي‬\n      ‫الشــبهة بــأن الغــرض مــن احليــازة الترويــج ومبــا أن الشــرع إذا حــرم شــيئا‬\n      ‫لذاتــه حــرم بيعــه و اقتنائــه ومبــا أن هــذه اجلنايــة وقعــت يف بلد اهلل احلرام‬\n      ‫الــذي رفــع اهلل مكانــه وتوعــد بالعقــاب علــى مــن انتهــك محارمــه ومبــا‬\n\n\n‫‪375‬‬\n\f‫أن التعزيــر يجــب بالشــبهة وهــو مشــروع يف كل معصيــة ال حــد فيهــا وال‬\n‫كفــارة وهــو يختلــف باختــاف األحــوال واألشــخاص والزمــان واملكان‬\n‫وتقديــر ذلــك راجــع إلــى نظــر احلاكــم جلميــع مــا ذكــر فقــد حكمــت‬\n‫مبــا يلــي أوال يجلــد املدعــى عليــه ثمانــن جلــدة حــد املســكر تقــع علــى‬\n‫بدنــه دفعــة واحــدة أمــام جمــع مــن النــاس ثانيــا يعــزر املدعــى عليــه وذلــك‬\n‫بجلــده مائتــي جلــدة تقــع علــى بدنــه علــى أربــع دفعــات متســاويات وبــن‬\n‫كل دفعــة و أخــرى عشــرة أيــام وبــن احلــد و التعزيــر مثــل ذلــك ويســجن‬\n‫خمســة أشــهر كاملــة ابتــداء مــن تاريــخ إيقافــه وبعرضــه قــرر املدعــي‬\n‫العــام عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة فأجيــب لطلبــه أمــا املدعــى عليــه فقــرر قناعتــه‬\n‫باحلكــم وقــد انتهــت اجللســة يف متــام الســاعة ‪ . 9 : 30‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪ 1434/04/01‬ه ـ‬\n          ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪34762502‬‬\n‫وتاريــخ ‪1434/4/2‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34176363‬وتاريــخ‬\n‫‪1434/4/1‬ه ـ ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪ ،..... /‬املتهــم يف‬\n‫قضيــة مســكر ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.......‬‬\n\n\n                                                                                        ‫‪376‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":372,"source_page_end":376,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"98fd3af12119153908afb34e261d7c33032ef23f9478feb87b7cc1cfba41f577","normalized_text_hash":"255af52bfb35a06ac2f91201bf723244510dfbcbbb8f1675d0029167b121e5f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p372-34176363"},{"id":"9d85452e-fcf2-5f09-961d-53eb3ca0776c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -اشتراك يف حيازة مسكر بقصد االستعمال -شرب املسكر -تعاطي حبوب محظورة -قيادة السيارة حتت تأثير املسكر -حد املسكر -تداخل التعازير إذا احتد جنسها -التعزير باجللد واملنع","document_number":"34316777","case_number":"34415532","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/10","year":"1434","subject":"مسكر -اشتراك يف حيازة مسكر بقصد االستعمال -شرب املسكر -تعاطي حبوب محظورة -قيادة السيارة حتت تأثير املسكر -حد املسكر -تداخل التعازير إذا احتد جنسها -التعزير باجللد واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                    ‫\t\t‬   ‫رقم الصك‪34316777 :‬‬\n    ‫تاريخه‪1434/09/10:‬هـ رقم الدعوى‪34415532:‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34358682:‬‬\n                          ‫تاريخه‪1434/11/12:‬ه‬\n\n\n         ‫مســكر ‪ -‬اشــتراك يف حيــازة مســكر بقصــد االســتعمال ‪ -‬شــرب املســكر‬\n         ‫‪ -‬تعاطــي حبــوب محظــورة ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬حــد‬\n         ‫املســكر‪ -‬تداخــل التعازيــر إذا احتــد جنســها‪ -‬التعزيــر باجللــد واملنــع‬\n                                                                         ‫مــن الســفر‪.‬‬\n\n\n\n\n         ‫‪ -1‬قــال تعالــى ( يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n                              ‫‪ -2‬قوله تعالى ( وال تلقوا بأيديكم إلى التهلكة ) ‪.‬‬\n         ‫‪ -3‬الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n                                                                  ‫واملؤثــرات العقليــة‬\n                    ‫‪ -4‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                    ‫‪ -5‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -6‬الفقرة الثامنة من جدول املخالفات رقم (‪ )1‬امللحق بنظام املرور‪.‬‬\n                         ‫‪ -7‬قرار مجلس الوزراء رقم ‪ 315‬تاريخ ‪1428/10/24‬هـ ‪.‬‬\n                        ‫‪ -8‬قرار هيئة كبار العلماء رقم ‪ 53‬تاريخ ‪1397/4/4‬هـ ‪.‬‬\n\n\n\n\n  ‫‪377‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليــه باشــتراكه مــع شــخص يف‬\n‫حيــازة مســكر بقصــد االســتعمال وشــرب املســكر وتعاطــي احلبــوب‬\n‫احملظــورة وقيــادة الســيارة حتــت تأثيرهمــا وطلــب إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه بحــد املســكر وســجنه ومنعــه مــن الســفر تعزيــر ًا لقــاء‬\n‫احليــازة وإفهامــه بــأن عقوبــة قيادتــه الســيارة حتــت تأثيــر املســكر عائــد‬\n‫للجهــة املختصــة وفــق األنظمــة والتعليمــات ‪،‬حيــث مت مالحظــة إحــدى‬\n‫املركبــات واالشــتباه بهــا فتــم اســتيقافها واتضــح أنهــا بقيــادة املدعــى‬\n‫عليــه ويرافقــه أحــد األشــخاص وبتفتيــش الســيارة عثــر علــى قــارورة‬\n‫يشــتبه باحتوائهــا علــى مســكر كمــا قــام أحدهمــا بالتلفــظ علــى رجال‬\n‫األمــن والبصــق عليهــم وعثــر علــى طلــق ناري فتم القبــض عليهما ‪ -‬أثبت‬\n‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة ملــادة الكحــول اإليثيلي‪،‬‬\n‫كمــا أثبــت تقريــر الســموم الشــرعي إيجابيــة عينــة ســوائل املدعــى عليــه‬\n‫ملركــب اإلمفيتامــن وصــادق املدعــى عليــه علــى الدعــوى‪ ،‬بنــاء علــى‬\n‫مــا تقــدم حكمــت احملكمــة جلــده حــد املســكر ثمانــن جلــدة دفعــة‬\n‫واحــدة علنـ ًا وجلــده ســتني جلــدة ومنعــه مــن الســفر خــارج اململكــة لقــاء‬\n‫حيــازة املســكر وتعاطــي احلبــوب احملظــورة وإفهامــه بــأن عقوبتــه لقــاء‬\n‫قيــادة الســيارة حتــت تأثيــر املســكر واحلبــوب املنبهــة عائــدة للجهــة‬\n‫املختصــة ورد طلــب املدعــي العــام معاقبــة املدعــى عليــه بعقوبــة الســجن‬\n‫الــواردة بالفقــرة (‪ )1‬مــن املــادة ‪ 41‬لعــدم انطباقهــا علــى املدعــى عليــه ‪،‬‬\n‫وصــدق‬‫قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                     ‫‪378‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 34415532‬وتاريــخ‬\n      ‫‪1434/09/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331942234‬وتاريــخ‬\n      ‫‪1433/11/02‬ه ـ ففــي يــوم اخلميــس املوافق‪1434/09/10‬ه ـ حضــر‬\n      ‫املدعــي العــام ‪.....‬كمــا حضــر املدعــى ‪ ،.....‬ســعودي رقــم ســجله املدنــي‬\n      ‫(‪ ).....‬وقــدم األول الئحــة دعــوى تتضمــن بــأن املدعــى عليــه ‪.....‬البالــغ‬\n      ‫مــن العمــر (‪ )26‬عام ـ ًا مت اإلفــراج عنــه بالكفالــة احلضوريــة بتاريــخ‬\n      ‫‪1433/8/28‬هــ‪ .‬بتاريخ‪1433/5/23‬هــ‪ ،‬اتضــح أنــه مت مالحظــة‬\n      ‫مركبــة مــن نــوع (‪ ).........‬صنــع عــام (‪2010‬م) ‪ ،‬حتمــل اللوحــة(‪).....‬‬\n      ‫واالشــتباه فيهــا فتــم اســتيقافها واتضــح أنهــا بقيــادة املتهــم املذكــور‬\n      ‫أعــاه ويرافقــه املدعــو‪ ،...../‬ســعودي اجلنســية‪ ،‬مبوجــب الهويــة الوطنية‬\n      ‫رقــم(‪ ).....‬وبتفتيــش الســيارة ُعثــر علــى قــارورة يشــتبه أنهــا حتتــوي‬\n      ‫علــى املســكر ‪ ،‬كمــا قــام أحدهمــا بالتلفــظ علــى رجــال املجاهديــن‬\n      ‫وعثــر أيضـ ًا علــى طلــق نــاري (فشــق) فتــم القبــض‬\n                                                            ‫ومقاومتهــم والبصــق ُ‬\n      ‫عليهمــا ‪ .‬وببعــث عينــة بــول ودم للمدعى عليه للمركز اإلقليمي ملراقبة‬\n      ‫الســموم لتحليلهــا فــورد تقريــر مركــز الســموم الشــرعية رقــم(‪)..... .....‬‬\n      ‫وتاري ــخ‪1433/5/25‬هـ ‪ ،‬متضمن ـ ًا إيجابيــة العينــات املرســلة للمــواد‬\n      ‫الكحولية(الكحــول اإليثيلــي) وايجابيــة عينــة البــول املرســلة ملركــب‬\n      ‫االمفيتامــن احملظــور ‪ .‬وببعــث عينــه مــن املضبــوط للمركــز اإلقليمــي‬\n      ‫ملراقبــة الســموم قســم الكيميــاء الشــرعية لفحصهــا ورد التقريــر‬\n      ‫الكيمــاوي الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1433/5/29‬ه ـ املتضمــن‬\n\n‫‪379‬‬\n\f‫ثبــوت احتــواء عينــة القــارورة املضبوطــة ملــادة الكحــول اإليثيلــي وبنســبة‬\n‫مســكره‪ .‬وانتهــى التحقيــق التهامــه باالشــتراك مــع مرافقــه (‪ ).....‬يف‬\n‫حيــازة قــارورة حتتــوي علــى املســكر بقصــد االســتعمال‪ ،‬وشــربه‬\n‫للمســكر ‪ ،‬وتعاطيــه للحبــوب احملظــورة وقيادتــه للســيارة حتــت‬\n‫تأثيرهمــا وذلــك لألدلــة والقرائــن املوضحــة بالالئحــة وبالبحــث عمــا إذا‬\n‫كان لديــه ســوابق‪ :‬تبــن عــدم وجــود ســوابق مســجلة ضــده ‪ .‬وحيــث أن‬\n‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه يف ضــوء الفقــرة الثانيــة‬\n‫مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫واحلكــم عليــه مبــا يلــي ‪-1-:‬حــد املســكر لقــاء شــربه لــه‪-2 .‬عقوبــة‬\n‫الســجن الــواردة يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام‬\n‫املشــار إليــه تعاطيــه للحبــوب احملظــورة ‪ ،‬واملــادة (‪)30‬مــن الالئحــة‬\n‫التنفيذيــة لــذات النظــام‪ -3 .‬منعــه مــن الســفر وفــق الفقــرة رقــم(‪ )1‬مــن‬\n‫املــادة رقــم (‪ )56‬مــن ذات النظــام‪ -4 .‬عقوبــة تعزيريــة لقــاء اشــتراكه‬\n‫مــع مرافقــه يف حيــازة قــارورة حتتــوي علــى املســكر بقصــد االســتعمال؛‬\n‫وتشــديد العقوبــة كونــه عســكري وفق ـ ًا لبرقيــة ســمو النائــب الثانــي‬\n‫وزيــر الداخليــة رقــم (‪/2/29371/4/5/1‬ش)وتاريــخ ‪1429/3/24‬هــ‪.‬‬\n‫‪ -5‬إثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر واحلبــوب‬\n‫احملظــورة وفــق الفقــرة رقم(‪)8‬مــن اجلــدول رقــم(‪ )1‬امللحــق بنظــام املــرور‬\n‫وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقم(‪)1‬مــن املــادة رقــم(‪ )68‬واملــادة‬\n‫رقم(‪)76‬مــن نظــام املــرور تقررهــا اجلهــة املختصــة وفــق الفقــرة رقــم(‪)2‬‬\n‫مــن قــرار مجلــس الــوزراء رقــم(‪)315‬يف ‪1428/10/24‬هــ‪ .‬هــذه دعــواي‬\n‫ا مــا ذكــره املدعــي العــام مــن‬ ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n\n\n                                                                                      ‫‪380‬‬\n\f      ‫اتهامــي باالشــتراك مــع (‪ ).....‬يف حيــازة قــارورة حتتــوي علــى املســكر‬\n      ‫بقصــد االســتعمال‪ ،‬وشــربي للمســكر ‪ ،‬وتعاطيــي للحبــوب احملظــورة‬\n      ‫وقيادتــي للســيارة حتــت تأثيرهمــا صحيــح لكننــي تبــت عــن ذلــك‬\n      ‫وأقلعــت عنــه منــذ خمســة أشــهر هكــذا أجاب‪،‬وبدراســة ملــف الدعــوى‬\n      ‫جــرى االطــاع علــى ســجل احلالــة اجلنائيــة والتقريــر الكيمــاوي املشــار‬\n      ‫لــه أعــاه فوجدتــه كمــا ذكــر املدعــي العــام ‪.‬وبنــاء علــى مــا تقــدم‬\n      ‫وحيــث تتلخــص دعــوى املدعــي العــام باتهــام املدعــى عليــه باالشــتراك‬\n      ‫يف حيــازة قــارورة حتتــوي علــى املســكر بقصــد االســتعمال‪ ،‬وشــرب‬\n      ‫للمســكر ‪ ،‬وتعاطــي للحبــوب احملظــورة وقيــادة الســيارة حتــت‬\n      ‫تأثيرهمــا ويطلــب معاقبتــه علــى ذلــك ‪ ،‬وألن هــذه احملكمــة مختصــة‬\n      ‫بنظــر هــذه الدعــوى بنــاء علــى املــواد (‪ )131,128‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وإلقــرار املدعــى عليــه وهــو بكامــل أهليتــه بجميــع مــا جــاء يف‬\n      ‫دعــوى املدعــي العــام وألن اإلقــرار حجــة علــى املقــر وألن مــا أقــدم عليــه‬\n      ‫مــن شــرب املســكر وتعاطــي احلبــوب املنبهــة احملظــورة وقيــادة الســيارة‬\n      ‫حتــت تأثيرهــا أفعــال محرمــة شــرع ًا لقولــه تعالــى ((إمنــا اخلمــر وامليســر‬\n      ‫واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه)) املائــدة‪90:‬‬\n      ‫وملــا يف تعاطــي هــذه احلبــوب مــن أضــرار صحيــة بالغــة كمــا أن قيــادة‬\n      ‫الســيارة حتــت تأثيــر املســكر فيهــا تعريــض للنفــس والغيــر للتهلكــة‬\n      ‫واهلل تعالــى يقــول (( وال تلقــوا بأيديكــم إلــى التهلكــة )) البقــرة ‪195:‬‬\n      ‫ومبــا أن تعاطــي احلبــوب املنبهــة احملظــورة مجــرم نظام ـ ًا وفق ـ ًا للفقــرة‬\n      ‫رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة كمــا أن قيــادة الســيارة حتــت تأثيــر املســكر و احلبــوب املنبهــة‬\n      ‫احملظــورة فعــل مجــرم نظام ـ ًا وفق ـ ًا للفقرة(‪)8‬مــن جــدول املخالفــات‬\n\n\n‫‪381‬‬\n\f‫رقــم (‪)1‬امللحــق بنظــام املــرور ‪،‬و ملــا نــص عليــه جماهيــر أهــل العلــم مــن‬\n‫أن حــد شــرب املســكر ثمانــن جلــدة وهــو مــا انتهــى إليــه قــرار هيئــة‬\n‫كبــار العلمــاء باململكــة ذي الرقــم رقــم ‪53‬يف ‪1397/4/4‬هــ‪ ،‬وملــا‬\n‫نــص عليــه الفقهــاء مــن أن التعزيــرات إذا كانــت حقـ ًا هلل واحتــد جنــس‬\n‫موجبهــا تداخلــت انظــر كشــاف القنــاع (‪ )113/14‬وبعــد االطــاع علــى‬\n‫املــواد(‪ )56،41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعلــى‬\n‫قــرار مجلــس الــوزراء رقــم(‪)315‬يف ‪1428/10/24‬هــ‪ .‬فقــد حكمــت‬\n‫باآلتــي‪ :‬أوالً‪ :‬إدانــة املدعــى عليــه احلاضر‪..........‬باالشــتراك يف حيــازة‬\n‫قــارورة حتتــوي علــى املســكر بقصــد االســتعمال‪ ،‬وشــربه للمســكر‬\n‫‪ ،‬وتعاطيــه للحبــوب احملظــورة وقيادتــه للســيارة حتــت تأثيرهمــا ثاني ـاً‪:‬‬\n‫جلــده حــد شــرب املســكر ثمانــن جلــدة دفعــة واحــدة علنـاً‪ .‬ثانيـاً‪ :‬جلــده‬\n‫ســتني جلــدة ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني تبــدأ مــن‬\n‫اكتســاب احلكــم القطعيــة عقوبــة علــى حيــازة املســكر وتعاطــي‬\n‫احلبــوب املنبهــة احملظــورة وأفهمتــه بــأن عقوبتــه علــى قيــادة الســيارة‬\n‫حتــت تأثيــر املســكر و احلبــوب املنبهــة احملظــورة تقــرر مــن اجلهــة‬\n‫املختصــة‪ .‬ورددت طلــب املدعــي العــام معاقبــة املدعــى عليــه بعقوبــة‬\n‫الســجن الــواردة بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬لعــدم انطباقهــا‬\n‫بحــق املدعــى عليــه وبإعــان احلكــم قــرر املدعــى عليــه عــدم اعتراضــه‬\n‫وقــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة حملكمــة االســتئناف‬\n‫دون تقــدمي الئحــة اعتراضيــة ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n\n\n                                                                                         ‫‪382‬‬\n\f      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ ‪.....‬‬\n      ‫برقــم ‪ 341942234‬وتاريــخ ‪1434/9/21‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/2281852‬وتاريــخ ‪1434/10/11‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلته املســجل برقــم ‪ 34316777‬وتاريــخ ‪1434/9/10‬هـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ .......... /‬يف قضيــة مســكر وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n      ‫القراروصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                        ‫حرريف‪1434/11/10‬ه ـ ‪.‬‬\n\n\n\n\n‫‪383‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":377,"source_page_end":383,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f8f33d9d547f612ff1f03a112088a18c008cc3c2846ec123d7570178132d235","normalized_text_hash":"c07ec7dbf3595de68d32bcb6ca9d5a8646afedfd4435ee85adeab8e7a62201dd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p377-34316777"},{"id":"c82f69e1-b673-59ce-b86c-4b24989153cd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة املسكر -قيادة السيارة حتت تأثير املسكر -مقاومة قوات الشرطة -رجوع عن إقرار مصدق شرع ا - درء حد املسكر -عدم وجود سوابق -التعزير باجللد.","document_number":"34344352","case_number":"34465050","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة حفر الباطن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/21","year":"1434","subject":"مسكر -شرب املسكر -حيازة املسكر -قيادة السيارة حتت تأثير املسكر -مقاومة قوات الشرطة -رجوع عن إقرار مصدق شرع ا - درء حد املسكر -عدم وجود سوابق -التعزير باجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 34344352:‬تاريخه ‪ 1434/10/21 :‬هـ‬\n                        ‫رقم الدعوى ‪34465050 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34372106 :‬‬\n                           ‫تاريخه‪1434/11/26:‬ه‬\n\n\n         ‫مســكر‪ -‬شــرب املســكر‪ -‬حيــازة املســكر ‪ -‬قيــادة الســيارة حتــت تأثيــر‬\n         ‫املســكر ‪ -‬مقاومــة قــوات الشــرطة ‪ -‬رجــوع عــن إقــرار مصــدق شــرع ًا ‪-‬‬\n                     ‫درء حــد املســكر ‪ -‬عــدم وجــود ســوابق ‪ -‬التعزيــر باجللــد‪.‬‬\n\n\n\n\n         ‫‪ -‬قولــه صلــى اهلل عليــه وســلم (لعنــت اخلمــرة بعينها وشــاربها وســاقيها‬\n         ‫وبائعهــا ومبتاعهــا وعاصرهــا ومعتصرهــا وحاملهــا واحملمولــة إليــه‬\n         ‫وآكل ثمنهــا ) رواه االمــام أحمــد وابــن ماجــه مــن طريــق عبــداهلل بــن‬\n                                        ‫عمــر رضــي اهلل عنهمــا وصححــه األلبانــي‬\n         ‫‪ -‬حيــازة املســكر وحملــه تعــد كبيــرة مــن كبائــر الذنــوب كمــا قــرر‬\n                                                ‫ذلــك الذهبــي يف كتابــه الكبائــر‪.‬‬\n\n\n\n\n         ‫مت توجيــه االتهــام للمدعــى عليــه بشــرب املســكر‪،‬وحيازته وقيــادة‬\n         ‫الســيارة حتــت تأثيــره‪ ،‬والهــرب مــن رجــال األمــن ‪ ،‬بالبحــث عن ســوابقه‬\n         ‫لــم يعثــر لــه علــى ســوابق ‪ ،‬طلــب املدعــي العــام احلكــم عليــه بحــد‬\n         ‫املســكر لقــاء شــربه لــه وبعقوبــة تعزيريــة لقــاء حيــازة املســكر والهــرب‬\n         ‫مــن رجــال األمــن وإفهامــه بــأن عقابــه علــى قيــادة الســيارة حتــت تأثيــر‬\n         ‫املســكر عائــد للجهــة املختصــة‪ ،‬بعــرض دعــوى املدعــي العــام علــى‬\n                                                                                             ‫‪384‬‬\n\f      ‫املدعــى عليــه صــادق علــى حيــازة املســكر بقصــد الشــرب وهروبــه مــن‬\n      ‫رجــال األمــن‪ ،‬وأنكــر شــرب املســكر وقيادتــه الســيارة حتــت تأثيــره‪،‬‬\n      ‫جــرى االطــاع علــى اعتــراف املدعــى عليــه حتقيقــا بشــرب املســكر‬\n      ‫وبعرضــه عليــه أنكــره‪ ،‬وألن املدعــى عليــه صــادق علــى حيازتــه للعــرق‬\n      ‫املســكر وأن قصــده مــن احليــازة الشــرب ومبــا أنــه أنكــر شــربه للعــرق‬\n      ‫املســكر وقيــادة الســيارة حتــت تأثيــره ومبــا أن حيــازة العــرق املســكر‬\n      ‫وحملــه يعــد كبيــرة مــن كبائــر الذنــوب‪ ،‬ومبــا أن املدعــى عليــه رجــع‬\n      ‫عــن اعترافــه بشــرب املســكر وألن احلــدود تــدرأ بالشــبهات ومبــا أن‬\n      ‫املدعــي العــام لــم يقــم بينــة علــى قيــام املدعــى عليــه بقيــادة الســيارة حتــت‬\n      ‫تأثيــر املســكر لــذا كلــه ثبتــت إدانــة املدعــى عليــه بحيــازة قــارورة ســعة‬\n      ‫نصــف لتــر بداخلهــا عــرق مســكر كمــا لــم يثبــت قيــام املدعــى عليــه‬\n      ‫بقيــادة الســيارة حتــت تأثيــر املســكر ومت احلكــم بــدرء حــد املســكر‬\n      ‫عــن املدعــى عليــه لرجوعــه عــن إقــراره وتعزيــره بجلــده تســعا وســبعني‬\n      ‫جلــدة لقــاء شــبهة شــربه للمســكر وجلــده خمس ـ ًا وســبعني جلــده لقــاء‬\n      ‫حيــازة املســكر وعــدم ثبــوت قيادتــه الســيارة حتــت تأثيــر املســكر‪،‬‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه قــرر قناعتــه باحلكــم كمــا قــرر‬\n      ‫املدعــي العــام اعتراضــه علــى احلكــم وطلــب رفعــه حملكمــة االســتئناف‬\n      ‫واالكتفــاء مبــا جــاء يف الئحــة الدعــوى‪ ،‬وبعــد رفــع احلكــم حملكمــة‬\n                                                    ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫‪385‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬مســاعد رئيــس احملكمــة العامــة‬\n‫مبحافظــة حفــر الباطــن وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بحفــر الباطــن برقــم ‪ 34465050‬وتاريــخ‬\n‫‪ 1434/10/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342377552‬وتاريــخ‬\n‫‪ 1434/10/21‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/10/26‬ه ـ‬\n‫افتتحــت اجللســة وحضــر فيهــا املدعــي العــام ‪...‬وأدعــى علــى احلاضــر ‪...‬‬\n‫ا يف دعــواه عليــه حيــث إنــه بتاريــخ‬‫ســعودي بالســجل املدنــي رقــم ‪...‬قائـ ً‬\n‫‪1434/8/2‬ه ـ وأثنــاء قيــام إحــدى الدوريــات األمنيــة مبحافظــة حفــر‬\n‫الباطــن بعملهــا مت مالحظــة ســيارة مــن نــوع ‪ ........‬حتمــل اللوحــة رقــم‬\n‫(‪ )...‬متوقفــة بجانــب مدرســة ‪ ........‬املتوســطة فتــم اســتيقاف قائدهــا‬\n‫إال أنــه الذ بالفــرار وتوقــف عنــد أحــد املنــازل ونــزل أحــد األشــخاص مــن‬\n‫الســيارة ودخــل املنــزل ويحمــل كيس ـ ًا يف يــده وبعــد إيقــاف املركبــة‬\n‫تبــن أنهــا بقيــادة املدعــى عليــه وبتفتيشــه عثــر بحوزتــه علــى (‪)0,5‬‬\n‫نصــف قــارورة مــاء بهــا الشــراب املســكر وقبــض عليــه وقــد انتهــى‬\n‫التحقيــق إلــى اتهامــه بحيــازة املســكر بقصــد الشــرب وشــربه لــه‬\n‫وقيادتــه الســيارة حتــت تأثيــره والهــرب مــن رجــال األمــن وبالبحــث عــن‬\n‫ســوابقه ‪ /‬لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم‬\n‫عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n‫شــرعا ونظامــا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــة واحلكــم عليــه‬\n‫‪ -1‬بحــد املســكر لقــاء شــربه لــه ‪ -2 .‬بعقوبــة تعزيريــة لقــاء حيــازة‬\n‫املســكر والهــرب مــن رجــال األمــن ‪ -3 .‬إفهامــه بــأن عقابــه علــى قيــادة‬\n\n                                                                                    ‫‪386‬‬\n\f      ‫الســيارة حتــت تأثيــر املســكر عائــد للجهــة املختصــة وفقــا للمــادة (‪)68‬‬\n      ‫مــن نظــام املــرور ‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائــا مــا‬\n      ‫ذكــره املدعــي العــام مــن أنــه قبــض علــي وبحوزتــي قــارورة ســعة نصــف‬\n      ‫لتــر فيهــا عــرق مســكر‪ ،‬وأنــي هربــت مــن رجــال األمــن فذلــك صحيــح‬\n      ‫ومــا ذكــره مــن أنــي شــربت العــرق املســكر وأنــي كنــت أقــود الســيارة‬\n      ‫حتــت تأثيــره فذلــك غيــر صحيــح هــذه إجابتــي وبعــد ســماع الدعــوى‬\n      ‫واإلجابــة جــرى ســؤال املدعــي العــام عــن بينتــه فيمــا أنكــره املدعــى‬\n      ‫عليــه قــال إن بينتــي ‪ -1‬اعترافــه املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n      ‫(‪ )3-1‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ -2 . )3‬محضــر القبــض‬\n      ‫املنــوه عنــه املرفــق لفــة رقــم (‪. )2‬وعنــد وصــول القضيــة عنــد هــذا احلــد‬\n      ‫رفعــت اجللســة لالطــاع علــى أوراق املعاملــة واعلــم الطرفــان باحلضــور‬\n      ‫يف يــوم األربعــاء املوافــق ‪ 1434/ 10/ 28‬ه ـ وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد حــرر يف ‪ 1434/ 10/ 26‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n      ‫يــوم األربعــاء املوافــق ‪1434/10/28‬ه ـ افتتحــت اجللســة الثانيــة وحضــر‬\n      ‫فيهــا املدعــي العــام واملدعــى عليــه وقــال املدعــى عليــه كان قصــدي مــن‬\n      ‫حيــازة العــرق املســكر الشــرب ثــم جــرى االطــاع علــى املعاملــة فوجــدت‬\n      ‫بــن طياتهــا اعتــراف املدعــى عليــه حتقيقــا املشــار إليــه ســابقا املتضمــن‬\n      ‫اعترافــه بشــربه للعــرق املســكر أثنــاء القبــض عليــه وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه قــال مــا جــاء يف اعتــرايف غيــر صحيــح وقــد اعترفــت بذلــك‬\n      ‫ألن احملقــق هددنــي إذا لــم اعتــرف فســوف يقــوم بســجني وبعــرض ذلــك‬\n      ‫علــى املدعــي العــام قــال ال علــم لــي بذلــك ثــم جــرى ســؤال املدعــي العــام‬\n      ‫هــل لديــه زيــادة بينــة قــال ليــس لــدي زيــادة بينــة فبنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن‬\n\n\n‫‪387‬‬\n\f‫أهليتــه وتأمــل أوراق املعاملــة ومبــا أن املدعــى عليــه صــادق علــى حيازتــه‬\n‫للعــرق املســكر وأن قصــده مــن احليــازة الشــرب ومبــا أنــه أنكــر شــربه‬\n‫للعــرق املســكر وقيــادة الســيارة حتــت تأثيــره ومبــا أن حيــازة العــرق‬\n‫املســكر وحملــه يعــد كبيــرة مــن كبائــر الذنــوب كمــا قــرر ذلــك‬\n‫الذهبــي يف كتابــه الكبائــر لقولــه صلــى اهلل عليــه وســلم (لعنت اخلمرة‬\n‫بعينهــا وشــاربها وســاقيها وبائعهــا ومبتاعهــا وعاصرهــا ومعتصرهــا‬\n‫وحاملهــا واحملمولــة إليــه وآكل ثمنهــا ) رواه االمــام أحمــد وابــن ماجــه‬\n‫مــن طريــق عبــداهلل بــن عمــر رضــي اهلل عنهمــا وصححــه األلبانــي‬\n‫ومبــا أن املدعــى عليــه رجــع عــن اعترافــه املتضمــن شــربه للمســكر‬\n‫وألن احلــدود تــدرأ بالشــبهات ومبــا أن املدعــي العــام لــم يقــم بينــة علــى‬\n‫قيــام املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املســكر لــكل مــا ســبق‬\n‫فقــد درأت حــد املســكر عــن املدعــى عليــه لرجوعــه عــن اعترافــه وبــه‬\n‫حكمــت وبعــده حكمــت عليــه بجلــده تســعا وســبعني جلــدة تعزيــرا لقاء‬\n‫شــبهة شــربه للمســكر كمــا ثبــت لــدي إدانــة املدعــى عليــه بحيــازة‬\n‫قــارورة ســعة نصــف لتــر بداخلهــا عــرق مســكر وبــه حكمــت وبعــده‬\n‫حكمــت عليــه بجلــده خمســا وســبعني جلــدة تعزيــرا لقــاء حيازتــه للعــرق‬\n‫املســكر ويكــون بعــد خمســة عشــر يومــا مــن عقوبــة اجللــد املنصــوص‬\n‫عليهــا أعــاه كمــا لــم يثبــت لــدي قيــام املدعــى عليــه بقيــادة الســيارة‬\n‫حتــت تأثيــر املســكر وبــه حكمــت وبعــرض ذلــك علــى املدعــى عليــه‬\n‫قــرر قناعتــه باحلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n‫وطلــب رفعــه حملكمــة االســتئناف واالكتفــاء مبــا جــاء يف الئحــة‬\n‫الدعــوى وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434 /10/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n                                                                                         ‫‪388‬‬\n\f      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة حفــر الباطــن برقــم‬\n      ‫‪ 342377552‬وتاريــخ ‪1434/11/3‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 342554201‬وتاريــخ ‪1434/11/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪......‬املســجل برقــم ‪34344352‬‬\n      ‫وتاريــخ ‪1434/10/28‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪.../‬يف‬\n      ‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                        ‫وصحبــه وســلم حــرر يف ‪1434/11/26‬ه ـ‬\n\n\n\n\n‫‪389‬‬\n\f390\n\f391\n\f392\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":384,"source_page_end":392,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1103b32207ff1969adfa6b533273ddc525d1598321b8c352711aeab6e4afa5cc","normalized_text_hash":"a5455745b10ada40e4ee893945e61b3f23caca120ed6e011c9d539a1ee61a2eb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p384-34344352"},{"id":"ca321062-d88d-5676-8cde-4fb0b8dcc263","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -ترويج مسكر -الدفع باجلهل ال يقبل قضاء ،عدم إطالة سجن األجنبي -اإلقرار -التعزير بالسجن لقاء ترويج املسكر.","document_number":"3432016","case_number":"3448064","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/06","year":"1434","subject":"مسكر -ترويج مسكر -الدفع باجلهل ال يقبل قضاء ،عدم إطالة سجن األجنبي -اإلقرار -التعزير بالسجن لقاء ترويج املسكر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3432016:‬تاريخه‪1434/02/06 :‬هـ‬\n                           ‫رقم الدعوى‪3448064:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34253813:‬تاريخه‪1434/06/27:‬هـ‬\n\n\n      ‫مســكر ‪ -‬ترويــج مســكر ‪ -‬الدفــع باجلهــل ال يقبــل قضــاء‪ ،‬عــدم إطالــة‬\n       ‫ســجن األجنبــي ‪ -‬اإلقــرار ‪ -‬التعزيــر بالســجن لقــاء ترويــج املســكر‪.‬‬\n\n\n\n\n                                              ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج اخلمــور عــن طريــق البيــع‬\n      ‫بقصــد الكســب املــادي وتســتره علــى مصــادر البيــع وطلــب املدعــي‬\n      ‫العــام إيقــاع العقوبــة التعزيريــة املشــددة عليــه حيــث توفــرت معلومــات‬\n      ‫عــن قيامــه بترويــج اخلمــر املســكر فجــرى إعــداد كمــن لــه وقبــض‬\n      ‫عليــه وهــو يقــوم بترويــج اخلمــر ‪ ،‬أثبــت التقريــر الكيميائــي ايجابيــة‬\n      ‫عينــة املضبوطــات ملــادة الكحــول املســكرة بنســبة ‪ -%42‬أقــر املدعــى‬\n      ‫عليــه لــدى جهــات التحقيــق بقيامــه بالترويــج بالبيــع ورفــض اإلدالء بــأي‬\n      ‫معلومــة حــول مصدرهــا ‪ ،‬كمــا أقــر املدعــى عليــه أثنــاء احملاكمــة‬\n      ‫بالترويــج ودفــع بأنــه ال يعلــم أن بيــع اخلمــر ممنــوع وأنــه ال يعلــم عــن البائــع‬\n      ‫شــيئا ســوى جنســيته ‪ ،‬بنــاء علــى مــا تقــدم قــررت احملكمــة تعزيــره‬\n      ‫بســجنه ملــدة أحــد عشــر شــهر ًا اعتبــار ًا مــن تاريــخ إيقافــه وجلــده مائــة‬\n      ‫وخمســن جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة خمســون جلــدة‬\n‫‪393‬‬\n\f‫بــن كل دفعــة واألخــرى مــدة ال تقــل عــن أســبوعني ‪ -‬قــرر املدعــي العــام‬\n‫واملدعــى عليــه االعتــراض علــى احلكــم وطلبــا تدقيقــه بــدون الئحــة ‪-‬‬\n                                 ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 3448064‬وتاريــخ ‪ 1434/01/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34237250‬وتاريــخ ‪ 1434/01/27‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/02/05‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام وادعــى قائــا بصف ــتي مدعيـ ـ ًا عامـ ـ ًا يف‬\n                           ‫دائ ــرة االدع ــاء الع ــام مبدينــة الريــاض أدع ــي علــى ‪/‬‬\n‫‪ 48...........‬ســنة ســيرالنكي اجلنســية إقامــة رقــم (‪ )...........‬اوقــف‬\n‫مبوجــب مذكــرة اإليقــاف رقــم ‪...........‬وتاريــخ ‪1433/11/28‬ه ـ ‪.‬‬\n‫حيــث انــه بتاريــخ ‪1433/11 27‬ه ـ ورد ملركــز شــرطة العليــا محضــر‬\n‫هيئة‪.............‬املتضمــن انــه توفــرت معلومــات عــن قيــام شــخص مــن‬\n‫اجلنســية الســيرالنكية يقــوم بترويــج اخلمــور فتــم االتصــال عليــه مــن‬\n‫قبــل احــد مصــادر الهيئــة واالتفــاق معــه علــى شــراء اربــع قواريــر مــن‬\n‫العــرق املســكر وحضــر شــخص يدعــى ‪(...................... /‬املدعــى عليــه)‬\n‫وبحوزتــه األربــع قواريــر املتفــق عليهــا ومت شــرائها منــه مببلــغ وقــدره ‪80‬‬\n‫ريــال للقــارورة الواحــدة وأعطــى املبلــغ املرقــم وأفــاد بانــه يحصــل علــى‬\n                     ‫اخلمــر مــن شــخص مــن نفــس اجلنســية يدعــى ‪............ /‬‬\n‫وقــد اثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )...........‬وتاريــخ‬\n\n                                                                                            ‫‪394‬‬\n\f      ‫‪1433/12/6‬ه ـ ايجابيــة عينــة املضبوطــات للكحــول املســكرة بنســبة‬\n                                                                                  ‫‪. %42‬‬\n      ‫وباســتجواب املدعــى عليــه اقــر بترويــج اخلمــور وانه مت االتصــال عليه من‬\n      ‫احــد مصــادر الهيئــة يطلــب منــه شــراء اربــع قواريــر مــن العــرق املســكر‬\n      ‫واالتفــاق معــه علــى بيــع األربــع قواريــر مببلــغ وقــدره (‪ )320‬ريــال حيــث‬\n      ‫تقابــا يف حــي ‪...........‬وقــام بتســليمه األربــع قواريــر واســتالم املبلــغ‬\n      ‫املرقــم ومت القبــض عليــه أثنــاء عمليــة التبايــع وبســؤاله عــن مصدر االربع‬\n      ‫قواريــر أفــاد بانــه قــام بشــرائها مــن شــخص مــن اجلنســية الســيرالنكية‬\n      ‫يدعــى (‪ )...........‬لــم يدلــي مبعلومــات اضافيــه عنــه وصــادق علــى اقــراره‬\n                                                                        ‫شــرعا بذلــك ‪.‬‬\n      ‫وقــد انتهــى التحقيــق الــى توجيــه االتهــام للمدعــى عليــه بترويــج اخلمــور‬\n      ‫عــن طريــق البيــع بقصــد الكســب املــادي وتســتره علــى مصــادر البيــع‬\n                                                  ‫وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪-1‬اقــراره املصــدق شــرعا املتضمــن قيامــه بترويــج اخلمــور لغــرض‬\n      ‫الكســب املــادي واملــدون مبلــف التحقيــق رقــم (‪ )2‬يف الصفحــة رقــم‬\n                                                                                 ‫(‪2. )1‬‬\n      ‫‪ -‬محضــر القبــض املعــد مــن مركــز هيئــة‪ ...........‬املتضمــن ضبطــه‬\n         ‫باجلــرم املشــهود اثنــاء عمليــة التبايــع وضبــط املبلــغ املرقــم بحوزتــه‬\n      ‫‪-3.‬التقريــر الكيميائــي الشــرعي املتضمــن ايجابيــة عينــة اخلمــور‬\n                             ‫املضبوطــة بحوزتــه ملــادة الكحــول بنســبة ‪.%42‬‬\n                          ‫وببحث سوابقه تبني عدم وجود سوابق مسجله عليه ‪.‬‬\n      ‫وحيــث إن مــا اقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n      ‫اطلــب احلكــم عليــه بعقوبــة تعزيريــة مشــددة هــذه دعــواي وبســؤال‬\n\n\n‫‪395‬‬\n\f‫املدعــى عليــه عــن دعــوى املدعــي املدعــي العــام أجــاب وهــو يحســن اللغــة‬\n‫العربيــة بقولــه مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيــا فلــم‬\n‫أكــن أعلــم أن بيــع اخلمــور ممنوعــا وال أعلــم عــن البائــع إال أنــه فلبينــي‬\n‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة‬\n‫املدعــى عليــه علــى دعــوى املدعــي العــام وملــا ورد يف التقريــر الكيميائــي‬\n‫الشــرعي املتضمــن ايجابيــة عينــة اخلمــور املضبوطــة بحوزتــه ملــادة‬\n‫الكحــول بنســبة ‪ %42‬وألن املذكــور أجنبــي نصرانــي الديانــة وقــد‬\n‫نــص التعميــم القضائــي علــى عــدم إطالــة ســجن األجنبــي لذلــك كلــه‬\n‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بترويــج اخلمــور عــن طريــق البيــع‬\n‫بقصــد الكســب املــادي وتســتره علــى مصــادر البيــع وحكمــت بتعزيــره‬\n‫بســجنه ملــدة أحــد عشــرة شــهر ًا اعتبــارا مــن تاريــخ إيقافــه وجلــده مائــة‬\n‫وخمســن جلــدة مفرقــة علــى ثــاث دفعــات علــى ان تكــون كل دفعــة‬\n‫خمســون جلــدة بــن كل دفعــة واألخــرى مــدة ال تقــل عــن أســبوعني‬\n‫وبعــرض ذلــك علــى الطرفــن قــررا عــدم القناعــة وطلبــا متييــز احلكــم‬\n‫بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/05‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 341021521‬وتاريخ‪1434/5/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪........... /‬املســجل برقــم ‪3432016‬‬\n‫وتاريخ‪1434/2/6‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪........... /‬‬\n‫(ســيرالنكي اجلنســية) التهامــه بترويــج اخلمــور علــى النحــو املوضــح‬\n\n\n                                                                                      ‫‪396‬‬\n\f      ‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫بعــد ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪397‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":393,"source_page_end":397,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e7ddf98e9a168e3929ed9b6e58f151670bafab4ce35680cc974291954e476726","normalized_text_hash":"d352b42e6a60b3f0ceee7aa9d2db351ed5efede9efc5ffe6d6a2b833bc6ced0c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p393-3432016"},{"id":"66a2e3cb-17b6-5bc3-a76e-34eb2287df4e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -ترويج مسكر -اإلقرار -التعزير بالسجن واجللد واإلبعاد لقاء ترويج املسكر -إقامة حد املسكر على املسلم -تعزير غير املسلم لشرب املسكر -ال يقام حد املسكر على الذمي او املستأمن .","document_number":"3429911","case_number":"3453324","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/04","year":"1434","subject":"مسكر -ترويج مسكر -اإلقرار -التعزير بالسجن واجللد واإلبعاد لقاء ترويج املسكر -إقامة حد املسكر على املسلم -تعزير غير املسلم لشرب املسكر -ال يقام حد املسكر على الذمي او املستأمن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 3429911:‬تاريخه‪1434/02/04 :‬هـ‬\n                     ‫رقم الدعوى‪3453324:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34183245:‬تاريخه‪1434/04/09:‬هـ‬\n\n\n‫مســكر ‪ -‬ترويــج مســكر ‪ -‬اإلقــرار ‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد‬\n‫لقــاء ترويــج املســكر ‪ -‬إقامــة حــد املســكر علــى املســلم ‪ -‬تعزيــر غيــر‬\n‫املســلم لشــرب املســكر ‪ -‬ال يقــام حــد املســكر علــى الذمــي او املســتأمن ‪.‬‬\n\n\n\n\n‫‪ -1‬ترويــج اخلمــر مــن اإلفســاد يف األرض وهــو معصيــة توجــب التعزيــر‬\n             ‫لقــول اهلل تعالــى ‪ « :‬وال تفســدوا يف األرض بعــد إصالحهــا»‪.‬‬\n‫‪ -2‬ترويــج اخلمــر مــن كبائــر الذنــوب حلديــث أنــس بــن مالــك‪:‬‬\n‫عاصرهــا‪،‬‬\n      ‫َ‬      ‫اخلم ـ ِر عشــر ًة‪:‬‬                           ‫الل ص َّلــى َّ ُ‬\n                               ‫الل ع َلي ـ ِه وس ـ َّل َم يف َ‬           ‫«لعـ َـن رســولُ َّ ِ‬\n‫وبائعهــا‪ ،‬واملبيوع َة‬\n                  ‫َ‬    ‫واملمولـ َة َل ُه‪،‬‬\n                                      ‫عتصرهــا‪ ،‬واملعصــور َة َلـ ُه‪ ،‬وحام َلهــا‪َ ،‬‬\n                                                                                   ‫َ‬        ‫وم‬\n                                                                                            ‫ُ‬\n‫ـرب «‪.‬‬\n     ‫الضـ ِ‬\n         ‫ـاقيها‪ ،‬واملســتقا َة َل ـ ُه ‪ ،‬ح َّتــى عـ َّـد عشــر ًة ‪ ،‬مــن هــذا َّ‬\n                                                                                ‫َل ـ ُه‪ ،‬وسـ َ‬\n‫أخرجــه ابــن ماجــه وصححــه األلبانــي ‪ ،‬واللعــن ال يكــون إال لكبيــرة ‪.‬‬\n‫‪ -3‬قــول البهوتــي ‪ -‬يف كشــاف القنــاع ‪ (:-‬وال يحــد ذمــي ومســتأمن‬\n‫بشــربه‪-‬أي املســكر‪ -‬ولــو رضــي بحكمنــا ‪ -‬ألنــه يعتقــد حلــه وذلــك‬\n                                                   ‫شــبهة يــدرأ بهــا احلــد )‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليهمــا األول والثانــي‬\n‫بترويــج املســكر وحيــازة (‪ )43‬قــارورة مــن املســكر بقصــد الترويــج‬\n\n                                                                                                 ‫‪398‬‬\n\f      ‫وقيــام األول والثالــث والرابــع بشــرب املســكر وطلــب املدعــي العــام‬\n      ‫مــا يلــي ‪ :‬إثبــات مــا أســند للمدعــى عليهــم‪ ،‬احلكــم علــى املدعــى عليــه‬\n      ‫األول بحــد املســكر‪ ،‬احلكــم علــى املدعــى عليــه األول والثانــي بعقوبــة‬\n      ‫تعزيريــة علــى قيامهمــا بترويــج املســكر وحيازتــه‪ ،‬احلكــم علــى‬\n      ‫املدعــى عليهمــا الثالــث والرابــع غيــر املســلمني بعقوبــة تعزيريــة مقابــل‬\n      ‫قيامهمــا بشــرب املســكر‪ ،‬حيــث مت القبــض علــى املدعــى عليهــم مــن‬\n      ‫قبــل الشــرطة اجلويــة بقاعــدة امللــك عبــد العزيــز اجلويــة بالظهــران مبقــر‬\n      ‫ســكنهم وبحوزتهــم (‪ )43‬قــارورة مــاء صحــة صغيــرة مملــوءة مبــادة‬\n      ‫املســكر املصنــع محليـ ًا أثبــت التقريــر الكيمــاوي الشــرعي إيجابيتهــا‬\n      ‫ملــادة الكحــول وبنســبة مســكرة ‪ -‬أقــر املدعــى عليهمــا األول والثانــي‬\n      ‫بصحــة التهمــة مبــا يف ذلــك حيــازة الكميــة املشــار لهــا يف الدعــوي‬\n      ‫وقيامهمــا بالترويــج وشــربهما املســكر‪ ،‬وأقــر األول بأنــه مســلم ‪-‬‬\n      ‫أقــر املدعــى عليــه الثالــث بقيامــه بشــرب املســكر وأنــه اشــتراه مــن‬\n      ‫املدعــى عليــه الثانــي وقــرر بأنــه نصرانــي ‪ -‬أقــر املدعــى عليــه الرابــع‬\n      ‫بقيامــه بشــرب املســكر وأنــه اشــتراه مــن املدعــى عليــه األول وقــرر‬\n      ‫بأنــه هندوســي‪ ،‬وألن املدعــى عليهمــا الثالــث والرابــع غيــر مســلمني‬\n      ‫فــا يقــام عليهمــا احلــد إال أنهمــا مســتحقان التعزيــر ملخالفتهمــا أنظمــة‬\n      ‫البــاد واإلقامــة فقــد قــررت احملكمــة احلكــم علــى املدعــى عليهــم مبــا‬\n      ‫يلــي ‪ :‬أوال ‪ /‬ثبــوت اشــتراك املدعــى عليــه األول والثانــي يف حيــازة ثــاث‬\n      ‫وأربعــن قــارورة حتتــوي علــى املســكر بقصــد الترويــج وقيامهمــا ببيــع‬\n      ‫املســكر وتعزيرهمــا ألجلــه بســجن كل واحــد منهمــا ســنه ونصــف‬\n      ‫مــن تاريــخ إيقافهمــا وجلــد كل واحــد منهمــا مئتــن وخمســن جلــدة‬\n      ‫علــى دفعــات متســاوية بــن كل دفعــة واألخــرى مــدة ال تقــل عــن عشــرة‬\n\n\n‫‪399‬‬\n\f‫أيــام ‪.‬ثانيــا ‪ /‬ثبــوت شــرب املدعــى عليــه األول للمســكر وجلــده لقــاء‬\n‫ذلــك حــد املســكر ثمانــن جلــده دفعــة واحــدة ويكــون بــن جلــده‬\n‫احلــد وجلــده التعزيــر مــدة ال تقــل عــن عشــرة أيــام‪ .‬ثالث ـ ًا ‪ /‬ثبــوت شــرب‬\n‫املدعــى عليهمــا الثالــث والرابــع للمســكر وتعزيرهمــا لقــاء ذلــك بجلــد‬\n‫كل واحــد منهمــا ســبعني جلــدة علــى دفعتــن متســاويتني بينهمــا مــدة‬\n‫ال تقــل عــن عشــرة أيــام‪ .‬رابع ــا ‪ /‬التوصيــة بإبعادهــم عــن البــاد فــور‬\n‫انتهــاء محكوميتهــم بعــد إنهــاء مــا لهــم ومــا عليهــم مــن حقــوق ‪ .‬وقنــع‬\n‫املدعــى عليهــم جميعــا باحلكــم وأمــا املدعــي العــام فقــرر عــدم القناعــة‬\n‫مكتفيــا مبــا قــدم بالالئحــة‪ُ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪...........‬القاضــي باحملكمــة اجلزائيــة باخلبر وبناء على املعاملة احملالة لنا‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائية يف محافظة اخلبر برقم ‪3453324‬‬\n‫وتاريــخ ‪ 1434/02/02‬ه ـ املقيــدة باحملكمــة برقــم ‪34264368‬‬\n‫وتاريخ‪1434/2/2‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/02/04‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9 : 15‬وفيهــا قــدم املدعــي العــام ‪...........‬‬\n                                                      ‫الئحــة دعــوى عامــة ضــد ‪:‬‬\n     ‫‪........... .1‬سيرالنكي اجلنسية مبوجب رخصة اإلقامة رقم ‪.............‬‬\n      ‫‪ ........... .2‬سيرالنكي اجلنسية مبوجب رخصة اإلقامة رقم ‪............‬‬\n      ‫‪ ........... .3‬سيرالنكي اجلنسية مبوجب رخصة اإلقامة رقم ‪...........‬‬\n       ‫‪ ............. .4‬نيبالي اجلنسية مبوجب رخصة اإلقامة رقم ‪................‬‬\n‫ا فيهــا حيــث إنــه بتاريــخ ‪1433/11/16‬ه ـ مت القبــض علــى املدعــى‬       ‫قائـ ً‬\n\n                                                                                       ‫‪400‬‬\n\f      ‫عليهــم مــن قبــل جنــاح الشــرطة اجلويــة بقاعــدة امللــك عبــد العزيــز اجلويــة‬\n      ‫بالظهــران مبقــر ســكنهم وبحوزتهــم عــدد (‪ )43‬قــارورة مــاء صحــة‬\n      ‫صغيــرة احلجــم مملــوءة مبــادة املســكر املصنــع محلي ـ ًا أثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي رقــم ( ‪ )......................‬وتاريــخ ‪1433 11/22‬ه ـ‬\n      ‫ايجابيــة العينــة املرســلة ملــادة الكحــول االيثيلــي وبنســبة مســكرة‬\n      ‫وباســتجواب املدعــى عليــه األول ‪ / ...........‬أفــاد أنــه قبــل أســبوعني مــن‬\n      ‫تاريــخ القبــض عليــه اســتلم عــدد (‪ )11‬قــارورة مملــوءة مبــادة املســكر‬\n      ‫املصنــع محلي ـ ًا مــن املدعــى عليــه الثاني‪.....................‬علــى أن يقــوم‬\n      ‫ببيعهــا وتروجيهــا وتســليمه علــى كل قــارورة مبلــغ ثالثــون ريــال وذلــك‬\n      ‫مقابــل راتــب شــهري قــدره (‪ )500‬خمســمائة ريــال حيــث قــام املدعــى‬\n      ‫عليــه الثانــي (‪ )......................‬بعــرض فكــرة ترويــج اخلمــور عليــه‬\n      ‫قبــل ســنة ورحــب بالفكــرة ووافقــه الــرأي وأن املدعــى عليــه الثانــي‬\n      ‫(‪ )......................‬يقــوم بإحضــار اخلمــور عــن طريــق شــخصني ال يعرفــه‬\n      ‫وال يعــرف كفالئهمــا وهمــا كال مــن املدعــو‪........... /‬و ‪)...........‬‬\n      ‫وأضــاف بأنــه بعــد اســتالمه للقواريــر تنــاول قارورتــن ونصــف وبقــي‬\n      ‫النصــف اآلخــر وقــام بوضعهــا بداخــل الغرفــة التــي يســكن بهــا حتــت‬\n      ‫ســريره وأفــاد بأنــه يقــوم بترويــج اخلمــور بداخــل مقــر ســكن الشــركة‬\n      ‫نقــد ًا وباآلجــل وباســتجواب املدعــى عليــه الثانــي ‪ /......................‬أفــاد‬\n      ‫أنــه قبــل ســنة قــام بعــرض فكــرة الترويــج علــى املدعــى عليــه األول‬\n      ‫(‪ )...........‬فوافقــه الــرأي ورحــب بالفكــرة وبعدهــا ذهــب اجــازة وبعــد‬\n      ‫عودتــه وبالتحديــد قبــل أســبوعني مــن القبــض عليــه قــام باســتالم عــدد‬\n      ‫(‪ )11‬قــارورة مملــوءة مبــادة املســكر املصنــع محلي ـ ًا (العــرق) علــى أن‬\n      ‫يقــوم بترويجهــا مببلــغ (‪ )30‬ثالثــن ريــال وذلــك مقابــل راتــب شــهري‬\n\n\n‫‪401‬‬\n\f‫قــدره (‪ )500‬خمســمائة ريــال حيــث يقــوم بإحضــار اخلمــور عــن طريــق‬\n‫ال مــن املدعــو‪/‬‬     ‫شــخصني ال يعرفــه وال يعــرف كفالئهمــا وهمــا ك ً‬\n‫(‪ )...........‬و(‪ )...........‬وأضــاف أنــه ال يعــرف بقيــة اســمائهما وأفــاد بأنــه‬\n‫كل أســبوع يقــوم باســتالم عــدد (‪ )25‬قــارورة قيمــة كل قــارورة (‪)23‬‬\n‫ثالثــة وعشــرون ريــال ويقــوم بترويجهــا علــى العمالــة بداخــل الســكن‬\n‫مبقــر الشــركة وأن الكميــة التــي ضبطــت وعددهــا (‪ )35‬قــارورة‬\n‫منهــا عــدد (‪ )3‬قواريــر فارغــة وجميعهــا تعــود لــه وكذلــك مــا مت‬\n‫ضبطــه بغرفتــه وعددهــا (‪ )6‬قواريــر باإلضافــة إلــى عــدد (‪ )3‬قواريــر‬\n‫فارغــة جميعهــا تعــود لــه ويقصــد مــن حيازتهــا ترويجهــا علــى العمالــة‬\n‫وباســتجواب املدعــى عليــه الثالــث ‪ /...........‬أفــاد بأنــه قبــل حوالــي شــهر‬\n‫تقريبـ ًا مــن القبــض عليــه قــام بشــراء عــدد (‪ )3‬قواريــر من مادة املســكر‬\n‫املصنــع محلي ـ ًا مببلــغ (‪ )90‬تســعون ريــا ًال مــن املدعــى عليــه الثانــي‬\n‫(‪ )...........‬وقــام بتناولهــا مبفــرده بداخــل الشــركة بالقاعــدة بالظهــران‬\n‫وباســتجواب املدعــى عليــه الرابــع ‪ /...........‬أفــاد بأنــه قبــل القبــض عليــه‬\n‫بقرابــة أربعــة أيــام تقابــل مــع املدعــى عليــه األول مبقــر ســكن الشــركة‬\n‫بداخــل القاعــدة اجلويــة بالظهــران وعــرض عليــه فكــرة شــراء قــارورة‬\n‫مســكر مصنــع محليـ ًا مببلــغ وقــدره (‪ )30‬ريــال فوافقــه علــى ذلــك وقــام‬\n                       ‫بإعطائــه الثــاث قواريــر وتنــاول قــارورة واحــدة فقــط ‪.‬‬\n‫‪ -‬لــم يوجــه االتهــام للمدعــو‪........... /‬ســريلنكي اجلنســية لعــدم ثبــوت‬\n‫عالقته بالقضية وانتهى التحقيق إلى توجيه االتهام لـ ‪...................... :‬و‬\n‫‪...........‬بترويــج املســكر وحيــازة عــدد (‪ )43‬قــارورة مــن املســكر بقصد‬\n‫الترويــج وشــرب املســكر لــأول وللمدعــى عليهمــا ‪...........‬و‪...........‬‬\n‫بشــرب املســكر ‪ -‬وذلــك لألدلــة والقرائــن اآلتيــة ‪ -1:‬اعترافهــم املــدون‬\n\n\n                                                                                        ‫‪402‬‬\n\f      ‫علــى ملفــات التحقيــق لفــات رقــم ( ‪-2) 3-2-1‬محضــر تنفيــذ مهمــة‬\n      ‫املرفــق لفــة رقــم(‪ -3 )16‬التقريــر الكيمــاوي الشــرعي املرفــق لفــه رقــم‬\n      ‫( ‪)18‬وبالبحــث عمــا إذا كان لهــم ســوابق لــم يعثــر لهــم علــى ســوابق‬\n      ‫جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليهــم ‪ -‬وهــم بكامــل‬\n      ‫أهليتهــم املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلب إثبات‬\n      ‫إدانتهــم مبــا أســند إليهــم واحلكــم علــى املدعــى عليــه األول (‪)...........‬‬\n      ‫بحــد املســكر لقــاء شــربه لــه وبعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم‬\n      ‫لقــاء قيــام املدعــى عليهمــا األول والثانــي بترويــج اخلمــور ‪ -‬وعلــى الثالــث‬\n      ‫والرابــع بعقوبــة تعزيريــة تزجرهمــا وتــردع غيرهمــا لقــاء شــربهما‬\n      ‫للمســكر هــذه دعــواي وبســؤال املدعــى عليهــم عــن الدعــوى بواســطة‬\n      ‫املترجــم املتعــاون ‪...........‬أجــاب املدعــى عليــه األول ‪ ...........‬بقولــه مــا جاء‬\n      ‫يف الدعــوى مــن حيازتــي أنــا واملدعــى عليــه الثانــي ‪...........‬لعــدد (‪)43‬‬\n      ‫ثــاث وأربعــن قــارورة مــاء صحــة صغيــرة حتتــوي علــى املســكر املصنــع‬\n      ‫محليـ ًا بقصــد الترويــج وترويجــي املســكر وشــربي املســكر هــذا كلــه‬\n      ‫صحيــح فقــد اتفقــت مــع املدعــى عليــه الثانــي ‪...........‬قبــل القبــض علينــا‬\n      ‫بأســبوعني علــى أن يقــوم هــو بإحضــار قواريــر املســكر وأقــوم أنــا‬\n      ‫ببيعهــا ويكــون العائــد املالــي مناصفــة بيننــا وقــد ســبق أن بعــت خمــس‬\n      ‫وخمســن قــارورة مــاء صحــة صغيــره احلجــم حتتــوي علــى املســكر علــى‬\n      ‫عــدة دفعــات بعتهــا علــى العمالــة املوجــودة معنــا يف الشــركة التــي نعمــل‬\n      ‫بهــا وذلــك بعــد أن أحضرهــا لــي املدعــى عليــه الثانــي ‪...........‬وتقاســمنا‬\n      ‫قيمتهــا مناصفــة والكميــة التــي ضبطهــا رجــال األمــن يف ســكننا وهــي‬\n      ‫ثــاث وأربعــن قــارورة مــاء صحــة صغيــره احلجــم حتتــوي علــى املســكر‬\n      ‫املصنــع محليـ ًا تعــود لــي أنــا واملدعــى عليــه الثانــي ‪...........‬بقصــد الترويــج‬\n\n\n‫‪403‬‬\n\f‫وأنــا أشــرب املســكر علمـ ًا بأنــي مســلم الديانــة هكــذا أجــاب وأجــاب‬\n‫املدعــى عليــه الثانــي ‪ ...........‬بقولــه مــا جــاء يف الدعــوى مــن حيازتــي أنــا‬\n‫واملدعــى عليــه األول ‪...........‬لعدد(‪)43‬ثــاث وأربعــون قــارورة مــاء صحــة‬\n‫صغيــرة احلجــم حتتــوي علــى املســكر املصنــع محلي ـ ًا بقصــد الترويــج‬\n‫وترويجــي املســكر هــذا كلــه صحيــح فقــد اتفقــت مــع املدعــى عليــه‬\n‫األول ‪...........‬قبــل القبــض علينــا بأســبوعني علــى أن أقــوم أنــا باحضــار‬\n‫قواريــر املســكر ويقــوم ‪...........‬ببيعهــا ويكــون العائــد املالــي مناصفــة‬\n‫بيننــا وقــد ســبق أن بعــت أنــا ثــاث قواريــر مســكر علــى العمالــة التــي‬\n‫تعمــل معنــا يف الشــركة كمــا أن املدعــى عليــه األول ‪...........‬قــام ببيــع‬\n‫خمســة وخمســن قــارورة حتتــوي علــى املســكر علــى عــدة دفعــات‬\n‫بعــد أن أحضرتهــا لــه وتقاســمت معــه قيمتهــا مناصفــة والكميــة التــي‬\n‫ضبطهــا رجــال األمــن يف ســكننا وهــي ثالثــة وأربعــن قــارورة مــاء‬\n‫صحــة صغيــرة احلجــم حتتــوي علــى املســكر املصنــع محلي ـ ًا تعــود لــي‬\n‫أنــا واملدعــى عليــه األول ‪...........‬بقصــد الترويــج هكــذا أجــاب وأجــاب‬\n‫املدعــى عليــه الثالــث ‪...........‬بقولــه مــا جــاء يف الدعــوى مــن شــربي‬\n‫املســكر هــذا صحيــح حيــث ســبق أن اشــتريت قبــل القبــض علــي‬\n‫بشــهر مــن املدعــى عليــه الثانــي ‪...........‬ثــاث قواريــر صغيــرة احلجــم‬\n‫حتتــوي علــى املســكر املصنــع محليـ ًا مببلــغ تســعني ريــا ًال وشــربت هــذا‬\n‫املســكر وأنــا نصرانــي الديانــة هكــذا أجــاب وأجــاب املدعــى عليــه‬\n‫الرابــع ‪...........‬بقولــه مــا جــاء يف الدعــوى مــن شــربي املســكر هــذا‬\n‫صحيــح فقــد اشــتريت قبــل القبــض علــي بأربعــة أيــام مــن املدعــى عليــه‬\n‫األول ‪......................‬قــارورة صغيــرة حتتــوي علــى املســكر مببلــغ ثالثــن‬\n‫ريــا ًال وشــربت هــذا املســكر وأنــا هندوســي الديانــة هكــذا أجــاب بعــد‬\n\n\n                                                                                          ‫‪404‬‬\n\f      ‫ذلــك جــرى الرجــوع إلــى اللفــة رقم(‪)4‬وتضمنــت بيــان باملضبوطــات‬\n      ‫ويظهــر منــه أن املضبــوط هــو ســت وأربعــن قــارورة منها(‪)41‬واحــد‬\n      ‫وأربعــون ســعة(‪500‬مل)و(‪)2‬قارورتان ســعه(‪250‬مل)و(‪)3‬ثالث قواريــر‬\n      ‫فارغــة كمــا جــرى الرجــوع إلــى اللفــة رقم(‪)18‬وتضمنــت صــورة التقرير‬\n      ‫ـاء‬\n      ‫الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي العــام يف دعــواه فبنـ ً‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليهمــا األول‬\n      ‫‪...........‬والثانــي ‪ ...........‬بحيازتهمــا املســكر بقصــد الترويــج وترويجهمــا‬\n      ‫للمكســر كمــا أقــر املدعــى عليه األول ‪......................‬بشــرب املســكر‬\n      ‫وحيــث إن فعلهمــا مــن كبائــر الذنــوب فقــد لعــن رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم يف اخلمــر ثمانيــة (شــاربها وســاقيها وحاملهــا واحملمولــة‬\n      ‫إليــه وعاصرهــا ومعتصرهــا وبائعهــا وآكل ثمنها)واللعــن ال يكــون‬\n      ‫إال علــى كبيــره مــن كبائــر الذنــوب كمــا أن يف ترويــج اخلمــور بــن‬\n      ‫النــاس نشــر للمنكــر وإشــاعة للســوء وهــو مــن اإلفســاد يف األرض واهلل‬\n      ‫تعالــى يقــول(وال تفســدوا يف األرض بعــد اصالحهــا) وحيــث أقــر املدعــى‬\n      ‫عليهمــا الثالــث ‪ .......‬والربــع ‪ ......‬بشــرب املســكر وحيــث إنهمــا غيــر‬\n      ‫مســلمني فــا يحــدان بشــرب املكســر قــال يف كشــاف القنــاع عــن‬\n      ‫مــن االقنــاع(‪(()101/5‬وال يحــد ذمــي مســتأمن بشــربه‪-‬أي املســكر‪-‬‬\n      ‫ولــو رضــي بحكمنــا ألنــه يعتقــد حلــه وذلــك شــبهة يــدرأ بهــا احلــد))‬\n      ‫وحيــث إنهمــا مســتحقان للتعزيــر ملخالفتهمــا أنظمــة البــاد واإلقامــة‬\n      ‫فيهــا وملــا جــاء يف بيــان املضبوطــات والتقريــر الكيمــاوي الشــرعي‬\n      ‫لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي اشــتراك املدعــى عليهمــا األول‬\n      ‫‪...........‬والثانــي ‪...........‬بحيــازة عــدد ثالثــة وأربعــن قــارورة حتتــوي علــى‬\n      ‫املســكر بقصــد الترويــج منهــا واحــد وأربعــن قــارورة ســعه(‪500‬مل)‬\n\n\n‫‪405‬‬\n\f‫وقارورتــن ســعه(‪250‬مل) وقيامهمــا ببيــع املســكر وقــررت تعزيرهمــا‬\n‫لقــاء ذلــك بســجن كل واحــد منهمــا مــدة ســنة ونصــف اعتبــار ًا مــن‬\n‫تاريــخ إيقافهمــا وجلــد كل واحــد منهمــا مائتــن وخمســن جلــده علــى‬\n‫خمــس دفعــات متســاوية بــن الدفعــة واألخــرى مــدة ال تقــل عــن عشــرة‬\n‫أيــام ثانيـ ًا ثبــت لــدي شــرب املدعــى عليــه األول ‪......................‬للمســكر‬\n‫وقــررت أن يجلــد لقــاء ذلــك حــد املســكر ثمانــن جلــده دفعــه واحــده‬\n‫ويكــون بــن جلــده احلــد وجلــده التعزيــر مــدة ال تقــل عــن عشــرة أيــام‬\n‫ثالث ـ ًا ثبــت لــدي شــرب املدعــى عليهمــا الثالــث ‪...........‬والرابــع ‪...........‬‬\n‫للمســكر وقــررت تعزيرهمــا لقــاء ذلــك بجلــد كل واحــد منهما ســبعني‬\n‫جلــده علــى دفعتــن متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام ومبــا‬\n‫تقــدم حكمــت وأوصيــت بإبعــاد املدعــى عليهــم عــن البــاد فــور انتهــاء‬\n‫محكوميتهــم بعــد إنهــاء مــا لهــم وعليهــم مــن حقــوق اتقــاء لشــرهم‬\n‫وبعــرض احلكــم قنــع املدعــى عليهــم جميع ـ ًا ولــم يقنــع املدعــي العــام‬\n‫مكتفيـ ًا مبــا قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة‬\n                                        ‫والنصــف وصلــى اهلل وســلم علــى نبينــا ‪..‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/787004‬ج‪ 2‬وتاريــخ ‪1434/04/01‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 34568152‬وتاريــخ ‪1434/3/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪........... /‬املســجل برقــم ‪3429911‬‬\n‫وتاريــخ ‪1434/2/4‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد كل ٍ مــن‬\n‫‪(.........../1‬ســيرالنكي اجلنســية) و‪(........... /2‬ســيرالنكي اجلنســية)‬\n\n\n                                                                                          ‫‪406‬‬\n\f      ‫‪(........... /3‬ســيرالنكي اجلنســية) و‪(...................... /4‬نبيالــي اجلنســية)‬\n      ‫يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/04/08‬هــ‪.‬‬\n\n\n\n\n‫‪407‬‬\n\f408\n\f409\n\f410\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":398,"source_page_end":410,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4d956ae13de0661c34c9bfc7a268499b76229abb74ef8b15b481f75aed1bb5e1","normalized_text_hash":"d3dca4817d2c44ae0fece7704f912d43889e515ba41deab01816b0659aa30500","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p398-3429911"},{"id":"6ec72037-7ddb-568c-badf-f41b4056d214","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى تشفيط بنزين -األصل يف املتهم البراءة -رفع التهمة مبا يضعفها -رد دعوى املدعي العام .","document_number":"34280904","case_number":"3486506","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/26","year":"1434","subject":"دعوى تشفيط بنزين -األصل يف املتهم البراءة -رفع التهمة مبا يضعفها -رد دعوى املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34280904 :‬تاريخه‪1434/7/26 :‬هـ‬\n                           ‫رقم الدعوى‪3486506:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34302308‬تاريخه‪1434/8/22 :‬هـ‬\n\n\n      ‫دعــوى تشــفيط بنزيــن ‪ -‬األصــل يف املتهــم البــراءة ‪ -‬رفــع التهمــة مبــا‬\n                                                 ‫يضعفهــا ‪ -‬رد دعــوى املدعــي العــام ‪.‬‬\n\n\n\n\n                                                ‫‪ -1‬قاعدة ‪ :‬األصل براءة الذمة ‪.‬‬\n                                       ‫‪ -2‬ما أشار له القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام ضــد املدعــى عليــه باستنشــاق‬\n      ‫مــادة البنزيــن وحيازتــه لقــارورة مــاء صغيــرة حتتــوي علــى مــادة البنزيــن‬\n      ‫بقصــد االستنشــاق وطلــب إيقــاع العقوبــة التعزيريــة عليــه ‪ ،‬حيــث‬\n      ‫قبضــت عليــه الدوريــات األمنيــة بعدمــا شــاهدته يقــود ســيارته بطريقــة‬\n      ‫غيــر متزنــة‪ ،‬فطلــب منــه الوقــوف‪ ،‬فظهــر عليــه عالمــات الســكر‪،‬‬\n      ‫وبتفتيــش الســيارة عثــر علــى قــارورة بهــا كميــة مــن البنزيــن ‪ ،‬فأجــري‬\n      ‫لــه حتليــل طبــي تبــن وجــود نســبة مــن مــادة البنزيــن يف دمه‪ ،‬أقــر املدعى‬\n      ‫عليــه باستنشــاقه مــادة البنزيــن إال أنــه دفــع بأنــه لــم يكــن ذلــك عمــدا‬\n      ‫بقصــد التأثيــر عليــه وإمنــا لنفــاد وقــود ســيارته فاضطــر لشــراء البنزيــن‬\n      ‫ووضعــه يف قــارورة ‪ ،‬وألن مفتــاح األمــان للخزان كان مغلقا قام بانتزاع‬\n      ‫خرطــوم املــاء املخصــص ملســاحات الســيارة وشــرع يف شــفط البنزيــن‬\n‫‪411‬‬\n\f‫مــن القــارورة وقــام بســكبه يف اخلــزان حتــى متكــن مــن تشــغيل محــرك‬\n‫الســيارة وتوجــه بهــا إلــى احملطــة فشــعر بعدهــا بعــدم اتــزان فقبــض عليــه‬\n‫قبــل أن يصــل للمحطــة وهــو علــى تلــك احلالــة فاتهــم بالتشــفيط ‪ -‬وبطلــب‬\n‫البينــة مــن املدعــي العــام قــرر بــأن بينتــه محضــر االســتجواب باملعاملــة‬\n‫ومحضــر القبــض ‪ -‬بعرضهمــا عليــه أقــر مبــا تضمنهمــا وأن موجــب مــا‬\n‫حصــل هــو مــا ورد يف جوابــه ولــم يكــن لغــرض غيــر مشــروع ‪ -‬جــرى‬\n‫االطــاع علــى صحيفــة الســوابق فلــم يعثــر علــى أي ســابقة مســجلة بحقه‬\n‫‪ -‬بنــاء علــى الدعــوى ‪ ،‬واإلجابــة ‪ ،‬وإلقــرار املدعــى عليــه ‪ ،‬وملــا دفــع بــه‬\n‫مــن أن مــا حصــل لــه لــم يكــن مقصــودا ولــم يكــن لغــرض ســيء بــل‬\n‫ألجــل تعبئــة ســيارته بالوقــود الــازم ‪ ،‬وألن األصــل بــراءة املســلم لذلــك‬\n‫فقــد قــررت احملكمــة عــدم ثبــوت إدانــة املدعــى عليــه بالتهمــة وانتهــت‬\n‫بــرد دعــوى املدعــي العــام يف طلبــه تعزيــر املدعــى عليــه ‪ -‬بعــرض احلكــم‬\n‫علــى املدعــي العــام قــرر عــدم القناعــة وطلــب رفــع القضيــة حملكمــة‬\n   ‫االســتئناف بــدون الئحــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...........‬املــازم القضائــي باحملكمــة‬\n‫اجلزائيــة باألحســاء وبنــاء علــى التعميــد املذيــل بالشــرح علــى املعاملــة‬\n‫لنظــري للقضيــة مــن قبــل فضيلــة القاضــي باحملكمــة الشــيخ ‪...........‬‬\n‫وبنــاء علــى املعاملــة الــواردة للمحكمــة مــن هيئــة التحقيــق واالدعــاء‬\n‫العــام باألحســاء برقــم ‪ 2590‬وتاريــخ ‪ 1434/2/20‬ه ـ واملقيــدة‬\n‫باحملكمــة برقــم ‪ 34440282‬وتاريــخ ‪1434/2/23‬ه ـ واحملالــة لنــا مــن‬\n‫فضيلــة ا لرئيــس برقــم ‪ 3486506‬وتاريــخ ‪ 1434/2/23‬ه ـ يف الســبت‬\n\n                                                                                       ‫‪412‬‬\n\f      ‫‪1434/4/20‬ه ـ افتتحــت اجللســة االولــى الســاعة العاشــرة والنصــف‬\n      ‫وفيهــا حضــر املدعــي ‪ ...........‬معمــد بالترافــع مــن دائــرة التحقيــق‬\n      ‫واالدعــاء العــام باألحســاء برقــم ‪...........‬يف ‪ 1433/12/1‬ه ـ ولــم يحضــر‬\n      ‫املدعــى عليــه ‪.............‬وبســؤال املدعــي العــام عــن دعــواه قــال بصفتــي‬\n      ‫عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‬      ‫مدعي ـ ًا ً‬\n      ‫‪ 33 ،...........:‬عامـ ًا ‪ ،‬املهنــة موظــف « قطــري اجلنســية « مبوجــب بطاقــة‬\n      ‫إثبــات الشــخصية رقــم ‪ ، ...........‬أوقــف بتاريــخ ‪1433/12/14‬ه ـ وأفــرج‬\n      ‫عنــه بالكفالــة ‪ ،‬يقيــم يف قطــر ‪ ،...........‬معــروف بواســطة كفيلــه‬\n      ‫املواطــن ‪ « ........... /‬ســعودي اجلنســية « مبوجــب الســجل املدنــي رقــم‬\n      ‫‪...........‬حيــث أنــه بتاريــخ ‪ 1433/12/14‬ه ـ مت القبــض علــى املدعــى‬\n      ‫عليــه مــن قبــل رجــال دوريــات أمــن الطــرق إثــر مشــاهدتهم لســيارة مــن‬\n      ‫نــوع ‪ ........‬بيضــاء اللــون حتمــل لوحــة قطريــة رقــم ‪ ..........‬يســير بطريقــة‬\n      ‫غيــر متزنــة ‪ ،‬وباســتيقافه لوحــظ بأنــه يف حالــة غيــر طبيعيــة ( ســكر‬\n      ‫) وبتفتيــش الســيارة عثــر بداخلهــا علــى قــارورة مــاء صحــة صغيــرة بهــا‬\n      ‫الربــع مــن مــادة البنزيــن ( ‪ ( ) 91‬مت إتالفهــا مــن قبــل جهــة الضبــط )‬\n      ‫‪ ،‬وباستشــمامه اتضــح انبعــاث رائحــة البنزيــن مــن جوفــه ‪ ،‬وقــد أثبــت‬\n      ‫التقريــر الطبــي رقــم ( ‪ )...........‬الصــادر مــن مستشــفى ……… وجــود‬\n      ‫أثــر ملــادة البنزيــن يف دمــه ‪.‬وباســتجواب املدعــى عليــه أقــر بواقعــة القبض‬\n      ‫عليــه واستنشــاقه ملــادة البنزيــن نــوع ( ‪ ) 91‬ملــدة عشــر دقائــق بعــد توقفــه‬\n      ‫بالقــرب مــن مركــز ‪...........‬باجتــاه ……… قبــل أن يواصــل ســيره‬\n      ‫‪.‬وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه باستنشــاق مــادة البنزيــن ‪،‬‬\n      ‫وحيازتــه لقــارورة مــاء صحــة صغيــرة بهــا الربــع مــن مــادة البنزيــن بقصــد‬\n                                    ‫االستنشــاق ؛ وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n\n\n‫‪413‬‬\n\f‫‪ - 1‬إقــراره املــدون علــى الصفحــة رقــم ( ‪ ) 2‬مــن دفتــر التحقيــق لفــة رقــم‬\n                                                                                 ‫(‪.)2‬‬\n‫‪ - 2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم ( ‪ ) 1‬مــن دفتــر‬\n                                                         ‫التحقيــق لفــة رقــم ( ‪. ) 2‬‬\n                                ‫‪ - 3‬محضر القبض املرفق على لفة رقم ( ‪. ) 5‬‬\n                            ‫‪ - 4‬محضر اإلتالف املرفق على لفة رقم ( ‪. ) 22‬‬\n                                ‫‪- 5‬التقرير الطبي املرفق على لفة رقم ( ‪. ) 32‬‬\n‫وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائيــة‬\n‫مســجلة ‪.‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه ش ــرع ًا ؛ أطلــب إثبــات مــا‬\n‫أســند إليــه ‪ ،‬واحلكــم عليــه بعقوبــة تعزيريــة لقــاء استنشــاقه ملــادة‬\n‫البنزيــن ‪ ،‬ولقــاء حيازتــه لقــارورة مــاء صحــة صغيــرة بهــا الربــع مــن مــادة‬\n                                    ‫البنزيــن بقصــد االستنشــاق ‪ .‬واهلل املوفــق ‪.‬‬\n‫وحلــن حضــور املدعــى عليــه ويف جلســة أخــرى حضــر الطرفــان وبعــد‬\n‫التأكــد مــن هويــة املدعــى عليــه جــرى عــرض دعــوى املدعــي العــام‬\n‫عليــه فقــال إن مــا ذكــره املدعــي العــام يف دعــواه مــن تشــفيطي ملــادة‬\n‫البنزيــن مــن فئــة (‪ )91‬صحيــح إال أنــه كان لســبب وهــو أنــي كنــت‬\n‫متوجهــا مــن الســعودية إلــى قطــر ويف أثنــاء الطريــق توقفــت الســيارة‬\n‫بالقــرب مــن هجــرة ‪ ...........‬فذهبــت حملطــة البنزين مع شــخص ال أعرفه‬\n‫ركبــت معــه بدراجتــه الناريــة وتوجهنــا حملطــة الوقــود وقمــت بشــراء‬\n‫البنزيــن ومــن ثــم رجعــت لســيارتي فلمــا أردت تعبئــة الســيارة بالبنزيــن‬\n‫وجــدت أن مفتــاح األمــان للبنزيــن مغلــق وال بــد مــن إدخــال ماســورة أو مــا‬\n‫شــابه فانتزعــت خرطــوم املــاء العائــد ملســاحات الســيارة وبــدأت أشــفط‬\n\n\n                                                                                         ‫‪414‬‬\n\f      ‫البنزيــن مــن القــارورة وأســكبه يف تانكــي الســيارة وملــا مت تشــغيل‬\n      ‫الســيارة توجهــت بهــا إلــى محطــة ‪...........‬وبعــد عمليــة الشــفط شــعرت‬\n      ‫بعــدم اتــزان يف قيادتــي بســبب شــفطي للبنزيــن وعلــى إثــره مت القبــض‬\n      ‫علــي مــن قبــل رجــال األمــن قبــل وصولــي للمحطــة واتهمــت بتشــفيط‬\n      ‫البنزيــن هــذا مــا حــدث هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام‬\n      ‫علــى صــدق دعــواه قــال بينتــي مــا جــاء يف أوراق املعاملــة اطلــب الرجــوع‬\n      ‫إليهــا فجــرى االطــاع علــى كــرت ســوابق املدعــى عليــه فلــم يعثــر لــه‬\n      ‫علــى ســوابق مســجله كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه‬\n      ‫يف محضــر االســتجواب لفــة رقــم (‪ )2‬علــى الصحيفــة (‪ ) 3- 2‬فوجــدت‬\n      ‫إقــرار املدعــى عليــه بشــفطه ملــادة البنزيــن ملــدة عشــر دقائــق وبعــرض‬\n      ‫ذلــك عليــه قــال مــا ذكــر محضــر الضبــط مــن إقــراري صحيــح إال انــه‬\n      ‫كان بســبب مــا ذكــرت ولــم يكــن لغــرض غيــر مشــروع فبنــاء علــى‬\n      ‫الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى دعــوى املدعــي يف‬\n      ‫شــفطه ملــادة البنزيــن ودفــع بأنــه كان لغــرض تعبئــة الســيارة إذ أنهــا‬\n      ‫كانــت متوفقــة بســبب نفــاذ البنزيــن يف ســيارته وهــذا مــا ذكــر يف‬\n          ‫محضــر االســتجواب املرصــود باللفــة رقــم (‪ )2‬علــى الصحيفــة رقــم‬\n      ‫(‪ ) 3- 2‬ولــم يكــن اســتعماله لغــرض ســيئ ومبــا أن األصــل يف الشــريعة‬\n      ‫اإلســامية البــراءة مــن مثــل هــذه األمــور ومبــا أن املدعــى عليــه خالــي‬\n      ‫مــن الســابق لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليــه‬\n      ‫مبــا يلــي أوال ‪ :‬لــم يثبــت لــدي إدانــة املدعــى عليــه شــفطه ملــادة البنزيــن‬\n      ‫لغــرض غيــر مشــروع ‪ -‬ثاني ـ ًا ‪ :‬رددت دعــوى املدعــي العــام يف طلــب‬\n      ‫تعزيــر املدعــى عليــه لقــاء شــفطه ملــادة البنزيــن وبعــرض احلكــم علــى‬\n      ‫املدعــي العــام قــرر عــدم قناعتــه بــه وطلــب رفــع كامــل أوراق املعاملــة‬\n\n\n‫‪415‬‬\n\f‫حملكمــة االســتئناف مكتفيــا مبــا قدمــه مــن أوراق واختتمــت اجللســة‬\n‫الســاعة العاشــرة وخمــس وأربعــن دقيقــة وبــاهلل التوفيــق وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه حــرر بتاريــخ ‪1434/7/26‬‬\n‫ه ـ احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء املكلــف‬\n‫برقــم ‪ 341976720‬وتاريــخ ‪1434/9/8‬ه ـ املقيــدة لــدى احملكمــة برقم‬\n‫‪ 34/2196715‬وتاريــخ ‪1434/9/16‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪...........‬املســجل برقــم‬\n‫‪ 34280904‬وتاريــخ ‪1434/7/26‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام‬\n‫ضد‪...........‬قطــري اجلنســية يف قضيــة تشــفيط وقــد تضمــن القــرار‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬قررنــا املصادقــة علــى‬\n‫احلكــم بعــد اإليضــاح األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/10/28‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                           ‫‪416‬‬\n\f417\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬    ‫م‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪5‬‬      ‫عليه وبتعزيره حليازته املسكر واالجتماع على‬   ‫شرب مسكر‬   ‫‪1‬‬\n                    ‫مفسدة بقصد الشرب‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪10‬‬                                                  ‫شرب مسكر‬   ‫‪2‬‬\n                         ‫عليه‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n           ‫عليهما وبتعزير األول على حيازة املسكر‬\n  ‫‪14‬‬                                                  ‫شرب مسكر‬   ‫‪3‬‬\n          ‫بقصد الشرب واآلخِ ر لقيادته السيارة حتت‬\n                       ‫تأثير املسكر‬\n\n\n         ‫دعوى عامة ضد مواطن بشربه مسكر حيث‬\n  ‫‪19‬‬      ‫وجد ملقى على األرض تنبعث منه رائحة‬          ‫شرب مسكر‬   ‫‪4‬‬\n                        ‫املسكر‬\n\n\n           ‫دعوى عامة ضد شخص لشربه املسكر‪،‬‬\n  ‫‪23‬‬      ‫ومقاومة رجال األمن‪ ،‬واالعتداء على مقيم‪،‬‬     ‫شرب مسكر‬   ‫‪5‬‬\n              ‫ضرب ًا والتستر على رفيقه الهارب‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪28‬‬                                                  ‫شرب مسكر‬   ‫‪6‬‬\n                         ‫عليه‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪34‬‬     ‫عليه وبتعزيره لتعاطيه احلشيش املخدر وقيادة‬   ‫شرب مسكر‬   ‫‪7‬‬\n                 ‫السيارة حتت تأثير املسكر‬\n\f‫الصفحة‬                    ‫املوضوع‬                     ‫التصنيف‬    ‫م‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪40‬‬                                                  ‫شرب مسكر‬   ‫‪8‬‬\n                         ‫عليه‬\n\n\n         ‫دعوى عامة بإقامة حد املسكر على املدعى‬\n  ‫‪44‬‬     ‫عليه وبتعزيره حليازته املسكر بقصد الشرب‬      ‫شرب مسكر‬   ‫‪9‬‬\n           ‫ولقيادته السيارة حتت تأثير املسكر‬\n\n\n         ‫دعوى عامة بتعزير ( 